const defaultCats=['Cuidadora','Fisioterapia','Medicamentos / Higiene','Dieta / Alimentação','Equipamentos','Consultas','Exames','Transporte','Hospital / Clínica','Farmácia','Outros'];
function Icon({children}){return <span className="ico">{children}</span>}
export default function App(){
 const [session,setSession]=useState(null); const [authLoading,setAuthLoading]=useState(true); const [dataLoading,setDataLoading]=useState(false); const [publicAuth,setPublicAuth]=useState(null); const [showOnboarding,setShowOnboarding]=useState(false);
 const [page,setPage]=useState('Dashboard'); const [bankTransactions,setBankTransactions]=useState([]); const [mobileMenuOpen,setMobileMenuOpen]=useState(false); const [rows,setRows]=useState([]); const [categories,setCategories]=useState([]); const [settings,setSettings]=useState(null); const [query,setQuery]=useState(''); const [selected,setSelected]=useState(null); const [controle,setControle]=useState(null); const [controles,setControles]=useState([]); const [members,setMembers]=useState([]); const [organizations,setOrganizations]=useState([]); const [organization,setOrganization]=useState(null); const [orgMembers,setOrgMembers]=useState([]); const [budgets,setBudgets]=useState([]); const [recurrences,setRecurrences]=useState([]); const [splits,setSplits]=useState([]); const [notice,setNotice]=useState(''); const [subscription,setSubscription]=useState(null); const [usage,setUsage]=useState(null); const [saasAdmin,setSaasAdmin]=useState(false); const [adminData,setAdminData]=useState(null);
 useEffect(()=>{supabase.auth.getSession().then(({data})=>{setSession(data.session);setAuthLoading(false)}); const {data:{subscription}}=supabase.auth.onAuthStateChange((_e,s)=>setSession(s)); return()=>subscription.unsubscribe()},[]);
 useEffect(()=>{if(session?.user){loadData();checkSaasAdmin(); const wanted=localStorage.getItem('ccai_selected_plan'); if(wanted){setPage('Assinatura');localStorage.removeItem('ccai_selected_plan')} if(!localStorage.getItem('ccai_onboarding_done'))setShowOnboarding(true)} else {setRows([]);setControle(null);setControles([]);setOrganization(null);setOrganizations([]);setSaasAdmin(false);setAdminData(null)}},[session?.user?.id]);
 async function authToken(){let {data:{session:s}}=await supabase.auth.getSession();if(!s?.access_token)return null;const expiresAt=Number(s.expires_at||0)*1000;if(expiresAt&&expiresAt-Date.now()<60000){const {data,error}=await supabase.auth.refreshSession();if(!error&&data?.session)s=data.session}return s?.access_token||null}
 async function adminMe(){const token=await authToken();if(!token)return {isAdmin:false};const r=await fetch('/api/admin/me',{headers:{Authorization:`Bearer ${token}`},cache:'no-store'});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||'Falha ao validar acesso administrativo.');return j}
 async function adminRequest(){const token=await authToken();if(!token)return null;const r=await fetch('/api/admin/overview',{headers:{Authorization:`Bearer ${token}`},cache:'no-store'});if(r.status===403)return null;const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||'Falha ao carregar Administração SaaS.');return j}
 async function checkSaasAdmin(){try{const me=await adminMe();setSaasAdmin(me.isAdmin===true);if(me.isAdmin){const j=await adminRequest();if(j)setAdminData(j)}else setAdminData(null)}catch(e){setSaasAdmin(false);setAdminData(null);console.error('Admin SaaS:',e);setNotice(`Admin SaaS: ${e.message}`)}}
 async function refreshAdmin(){try{setDataLoading(true);const me=await adminMe();if(!me.isAdmin){setSaasAdmin(false);setAdminData(null);setNotice('Acesso administrativo não autorizado.');return}const j=await adminRequest();if(!j){setSaasAdmin(false);setAdminData(null);setNotice('Acesso administrativo não autorizado.');return}setAdminData(j);setSaasAdmin(true)}catch(e){setNotice(e.message)}finally{setDataLoading(false)}}
 async function loadData(preferredControlId=null,preferredOrgId=null){setDataLoading(true);await supabase.rpc('aceitar_meus_convites_org');await supabase.rpc('aceitar_meus_convites');let {data:orgs,error:orgError}=await supabase.from('organizacoes').select('*').eq('ativo',true).order('created_at');if(orgError){setNotice('Organizações: '+orgError.message);setDataLoading(false);return}if(!orgs||orgs.length===0){const r=await supabase.rpc('criar_organizacao',{p_nome:'Minha organização',p_email:session.user.email});if(r.error){setNotice(r.error.message);setDataLoading(false);return}orgs=[r.data]}setOrganizations(orgs);const wantedOrg=preferredOrgId||organization?.id;const org=orgs.find(x=>x.id===wantedOrg)||orgs[0];setOrganization(org);setSettings({...org,nome_empresa:org.nome,nome_exibicao:org.nome});const om=await supabase.from('organizacao_membros').select('*').eq('organizacao_id',org.id).order('created_at');setOrgMembers(om.data||[]);let {data:cs,error:controlsError}=await supabase.from('controles').select('*').eq('organizacao_id',org.id).eq('ativo',true).order('created_at');if(controlsError){setNotice('Controles: '+controlsError.message);setDataLoading(false);return}if(!cs||cs.length===0){const r=await supabase.from('controles').insert({user_id:session.user.id,organizacao_id:org.id,nome:'Meu controle'}).select().single();if(r.error){setNotice(r.error.message);setDataLoading(false);return}cs=[r.data]}setControles(cs);const wanted=preferredControlId||controle?.id;const c=cs.find(x=>x.id===wanted)||cs[0];setControle(c);let {data:catData,error:catError}=await supabase.from('categorias').select('*').eq('organizacao_id',org.id).order('nome');if(!catError&&(!catData||catData.length===0)&&org.owner_id===session.user.id){await supabase.from('categorias').insert(defaultCats.map((nome,i)=>({user_id:session.user.id,organizacao_id:org.id,nome,descricao:'Categoria inicial do ContaClaraAI',ativo:true,ordem:i})));const rr=await supabase.from('categorias').select('*').eq('organizacao_id',org.id).order('nome');catData=rr.data||[]}if(catError)setNotice('Categorias: '+catError.message);else setCategories(catData||[]);const {data,error}=await supabase.from('despesas').select('*').eq('controle_id',c.id).order('data',{ascending:false}).order('created_at',{ascending:false});if(error)setNotice(error.message);else setRows((data||[]).map(dbToRow));const bankr=await supabase.from('transacoes_bancarias').select('*').eq('controle_id',c.id).order('data',{ascending:false}).order('created_at',{ascending:false});setBankTransactions(bankr.data||[]);const mr=await supabase.from('controle_membros').select('*').eq('controle_id',c.id).order('created_at');setMembers(mr.data||[]);const [br,rr,sr]=await Promise.all([supabase.from('orcamentos').select('*').eq('controle_id',c.id).order('mes',{ascending:false}),supabase.from('despesas_recorrentes').select('*').eq('controle_id',c.id).order('created_at',{ascending:false}),supabase.from('rateios').select('*').eq('controle_id',c.id).order('created_at',{ascending:false})]);setBudgets(br.data||[]);setRecurrences(rr.data||[]);setSplits(sr.data||[]);const [subr,usgr]=await Promise.all([supabase.from('assinaturas').select('*,planos_saas(*)').eq('organizacao_id',org.id).maybeSingle(),supabase.rpc('meu_consumo_saas',{p_organizacao:org.id})]);setSubscription(subr.data||null);setUsage(usgr.data||null);setDataLoading(false)}
 async function switchOrganization(id){setSelected(null);setQuery('');setControle(null);await loadData(null,id);setPage('Dashboard')}
 async function createOrganization(form){const nome=form.nome?.trim();if(!nome)return false;const {data,error}=await supabase.rpc('criar_organizacao',{p_nome:nome,p_email:session.user.email});if(error){setNotice(error.message);return false}setNotice('Organização criada com sucesso.');await loadData(null,data.id);return true}
 async function inviteOrgMember(email,papel){if(!organization)return false;const normalized=email.trim().toLowerCase();const {error}=await supabase.from('organizacao_membros').upsert({organizacao_id:organization.id,email:normalized,papel,status:'pendente',convidado_por:session.user.id,updated_at:new Date().toISOString()},{onConflict:'organizacao_id,email'});if(error){setNotice(error.message);return false}setNotice('Convite da organização registrado.');await loadData(controle?.id,organization.id);return true}
 async function changeOrgMember(id,papel){const {error}=await supabase.from('organizacao_membros').update({papel,updated_at:new Date().toISOString()}).eq('id',id);if(error)setNotice(error.message);else await loadData(controle?.id,organization.id)}
 async function removeOrgMember(id){const {error}=await supabase.from('organizacao_membros').delete().eq('id',id);if(error)setNotice(error.message);else await loadData(controle?.id,organization.id)}
 async function switchControl(id){setSelected(null);setQuery('');await loadData(id);setPage('Dashboard')}
 async function createControl(form){const nome=form.nome?.trim();if(!nome)return false;const {data,error}=await supabase.from('controles').insert({user_id:session.user.id,organizacao_id:organization.id,nome,descricao:form.descricao?.trim()||null}).select().single();if(error){setNotice(error.message);return false}setNotice('Controle criado com sucesso.');await loadData(data.id);return true}
 async function updateControl(form){if(!controle||controle.user_id!==session.user.id)return false;const {error}=await supabase.from('controles').update({nome:form.nome.trim(),descricao:form.descricao?.trim()||null,updated_at:new Date().toISOString()}).eq('id',controle.id);if(error){setNotice(error.message);return false}setNotice('Controle atualizado.');await loadData(controle.id);return true}
 async function inviteMember(email,papel){if(!controle||controle.user_id!==session.user.id){setNotice('Somente o proprietário pode convidar membros.');return false}const normalized=email.trim().toLowerCase();if(!normalized)return false;const {error}=await supabase.from('controle_membros').upsert({controle_id:controle.id,email:normalized,papel,status:'pendente',convidado_por:session.user.id,updated_at:new Date().toISOString()},{onConflict:'controle_id,email'});if(error){setNotice(error.message);return false}setNotice('Convite registrado. Quando esse e-mail entrar no ContaClaraAI, o acesso será ativado automaticamente.');await loadData(controle.id);return true}
 async function changeMember(id,papel){const {error}=await supabase.from('controle_membros').update({papel,updated_at:new Date().toISOString()}).eq('id',id);if(error)setNotice(error.message);else{setNotice('Permissão atualizada.');await loadData(controle.id)}}
 async function removeMember(id){const {error}=await supabase.from('controle_membros').delete().eq('id',id);if(error)setNotice(error.message);else{setNotice('Membro removido do controle.');await loadData(controle.id)}}
 async function saveExpense(f,file,stay=false){setDataLoading(true);let path=null,name=null;if(file){name=file.name;path=`${session.user.id}/${crypto.randomUUID()}-${safeName(file.name)}`;const up=await supabase.storage.from('comprovantes').upload(path,file,{contentType:file.type,upsert:false});if(up.error){setNotice('Falha no upload: '+up.error.message);setDataLoading(false);return false}}
  const payload={user_id:session.user.id,controle_id:controle?.id,data:f.date,descricao:f.desc,categoria:f.cat,valor:Number(f.value),pagador:f.payer,fornecedor:f.supplier,status:f.status,forma_pagamento:f.method,observacoes:f.notes||null,comprovante_path:path,comprovante_nome:name,pix_transacao_id:f.pixTransactionId||null,origem:f.origem||'manual',ia_confianca:f.aiConfidence?Number(f.aiConfidence):null,ia_dados:f.aiData||null}; if(payload.pix_transacao_id){const dup=await supabase.from('despesas').select('id,descricao,data,valor').eq('controle_id',controle?.id).eq('pix_transacao_id',payload.pix_transacao_id).limit(1);if(dup.data?.length){if(path)await supabase.storage.from('comprovantes').remove([path]);setNotice('Possível duplicidade: já existe uma despesa com este identificador PIX.');setDataLoading(false);return false}} const {error}=await supabase.from('despesas').insert(payload);if(error){if(path)await supabase.storage.from('comprovantes').remove([path]);setNotice(error.message);setDataLoading(false);return false}else{setNotice('Despesa salva com sucesso.');await loadData();if(!stay)setPage('Despesas')}setDataLoading(false);return true}
 async function updateExpense(r,f){setDataLoading(true);const payload={data:f.date,descricao:f.desc.trim(),categoria:f.cat,valor:Number(f.value),pagador:f.payer?.trim()||null,fornecedor:f.supplier?.trim()||null,status:f.status,forma_pagamento:f.method,observacoes:f.notes?.trim()||null};const {data,error}=await supabase.from('despesas').update(payload).eq('id',r.id).select().single();if(error){setNotice('Falha ao atualizar despesa: '+error.message);setDataLoading(false);return false}const updated=dbToRow(data);setSelected(updated);setNotice('Despesa atualizada com sucesso.');await loadData();setPage('Detalhe');setDataLoading(false);return true}
 async function removeExpense(r){if(r.proofPath)await supabase.storage.from('comprovantes').remove([r.proofPath]);const {error}=await supabase.from('despesas').delete().eq('id',r.id);if(error)setNotice(error.message);else{await loadData();setPage('Despesas')}}
 async function openProof(r){if(!r.proofPath)return;const {data,error}=await supabase.storage.from('comprovantes').createSignedUrl(r.proofPath,60);if(error)setNotice(error.message);else window.open(data.signedUrl,'_blank','noopener,noreferrer')}
 async function attachProof(r,file){if(!file)return;setDataLoading(true);if(file.size>10485760){setNotice('O comprovante deve ter no máximo 10 MB.');setDataLoading(false);return}const allowed=['application/pdf','image/jpeg','image/png','image/webp'];if(file.type&&!allowed.includes(file.type)){setNotice('Formato não permitido. Use PDF, JPG, PNG ou WEBP.');setDataLoading(false);return}const path=`${session.user.id}/${crypto.randomUUID()}-${safeName(file.name)}`;const up=await supabase.storage.from('comprovantes').upload(path,file,{contentType:file.type,upsert:false});if(up.error){setNotice('Falha no upload: '+up.error.message);setDataLoading(false);return}const {error}=await supabase.from('despesas').update({comprovante_path:path,comprovante_nome:file.name}).eq('id',r.id);if(error){await supabase.storage.from('comprovantes').remove([path]);setNotice(error.message)}else{if(r.proofPath)await supabase.storage.from('comprovantes').remove([r.proofPath]);setNotice('Comprovante anexado com sucesso.');await loadData();setSelected(x=>x?{...x,proof:file.name,proofPath:path}:x)}setDataLoading(false)}
 async function saveCategory(cat){const payload={user_id:session.user.id,organizacao_id:organization.id,nome:cat.nome.trim(),descricao:cat.descricao?.trim()||null,ativo:cat.ativo};let res=cat.id?await supabase.from('categorias').update(payload).eq('id',cat.id):await supabase.from('categorias').insert(payload);if(res.error){setNotice(res.error.message);return false}setNotice(cat.id?'Categoria atualizada.':'Categoria adicionada.');await loadData();return true}
 async function saveSettings(form,logoFile){setDataLoading(true);let logoPath=organization?.logo_path||null,logoUrl=organization?.logo_url||null;if(logoFile){if(logoFile.size>5242880){setNotice('O logotipo deve ter no máximo 5 MB.');setDataLoading(false);return false}const path=`${session.user.id}/${crypto.randomUUID()}-${safeName(logoFile.name)}`;const up=await supabase.storage.from('identidade').upload(path,logoFile,{contentType:logoFile.type,upsert:false});if(up.error){setNotice(up.error.message);setDataLoading(false);return false}logoPath=path;logoUrl=supabase.storage.from('identidade').getPublicUrl(path).data.publicUrl}const payload={nome:form.nome_empresa.trim()||'Minha organização',documento:form.documento?.trim()||null,email:form.email?.trim()||null,telefone:form.telefone?.trim()||null,cep:form.cep?.trim()||null,endereco:form.endereco?.trim()||null,numero:form.numero?.trim()||null,complemento:form.complemento?.trim()||null,bairro:form.bairro?.trim()||null,cidade:form.cidade?.trim()||null,uf:form.uf?.trim()?.toUpperCase()||null,cor_primaria:form.cor_primaria||'#0877f9',logo_path:logoPath,logo_url:logoUrl,updated_at:new Date().toISOString()};const res=await supabase.from('organizacoes').update(payload).eq('id',organization.id).select().single();if(res.error){setNotice(res.error.message);setDataLoading(false);return false}setOrganization(res.data);setSettings({...res.data,nome_empresa:res.data.nome,nome_exibicao:res.data.nome});setOrganizations(x=>x.map(o=>o.id===res.data.id?res.data:o));setNotice('Configurações da organização salvas.');setDataLoading(false);return true}

 async function saveBudget(f){const mes=(f.mes||'').slice(0,7)+'-01';const payload={controle_id:controle.id,organizacao_id:organization.id,user_id:session.user.id,mes,limite_geral:Number(f.limite_geral||0),categoria:f.categoria||null,limite_categoria:f.categoria?Number(f.limite_categoria||0):null};const {error}=await supabase.from('orcamentos').upsert(payload,{onConflict:'controle_id,mes,categoria'});if(error){setNotice(error.message);return false}setNotice('Orçamento salvo.');await loadData(controle.id,organization.id);return true}
 async function saveRecurrence(f){const payload={controle_id:controle.id,organizacao_id:organization.id,user_id:session.user.id,descricao:f.descricao,categoria:f.categoria,valor:Number(f.valor),dia_vencimento:Number(f.dia_vencimento),pagador:f.pagador||null,fornecedor:f.fornecedor||null,forma_pagamento:f.forma_pagamento||null,ativo:true};const {error}=await supabase.from('despesas_recorrentes').insert(payload);if(error){setNotice(error.message);return false}setNotice('Despesa recorrente cadastrada.');await loadData(controle.id,organization.id);return true}
 async function toggleRecurrence(r){const {error}=await supabase.from('despesas_recorrentes').update({ativo:!r.ativo,updated_at:new Date().toISOString()}).eq('id',r.id);if(error)setNotice(error.message);else await loadData(controle.id,organization.id)}
 async function saveSplit(f){const participantes=(f.participantes||'').split(',').map(x=>x.trim()).filter(Boolean);if(participantes.length<2){setNotice('Informe ao menos duas pessoas no rateio.');return false}const {error}=await supabase.from('rateios').insert({controle_id:controle.id,organizacao_id:organization.id,user_id:session.user.id,descricao:f.descricao,valor_total:Number(f.valor_total),pago_por:f.pago_por,participantes,observacoes:f.observacoes||null});if(error){setNotice(error.message);return false}setNotice('Rateio registrado.');await loadData(controle.id,organization.id);return true}

 if(authLoading)return <div className="authPage"><div className="authCard"><h2>ContaClaraAI</h2><p>Carregando...</p></div></div>;
 if(!session)return publicAuth?<Auth initialMode={publicAuth} back={()=>setPublicAuth(null)}/>:<Landing onLogin={()=>setPublicAuth('login')} onSignup={(plan)=>{if(plan)localStorage.setItem('ccai_selected_plan',plan);setPublicAuth('signup')}}/>;
 const total=rows.reduce((a,b)=>a+Number(b.value),0); const paid=rows.filter(x=>x.status==='Pago').reduce((a,b)=>a+Number(b.value),0); const pending=total-paid;
 const byCat=Object.entries(rows.reduce((a,r)=>{a[r.cat]=(a[r.cat]||0)+Number(r.value);return a},{})).sort((a,b)=>b[1]-a[1]); const nav=['Dashboard','Despesas','Comprovantes','Importar WhatsApp','Categorias','Pessoas','Financeiro','Conciliação Bancária','Relatórios','Controles','Organizações','Assinatura','Configurações',...(saasAdmin?['Admin SaaS']:[])]; const brandName=settings?.nome_exibicao||settings?.nome_empresa||'ContaClaraAI'; const primary=settings?.cor_primaria||'#0877f9';
 return <div className={`shell ${mobileMenuOpen?'mobileMenuOpen':''}`} style={{'--primary':primary}}><div className="mobileTopbar"><button className="mobileMenuButton" aria-label="Abrir menu" onClick={()=>setMobileMenuOpen(true)}>☰</button><div className="mobileBrand">{settings?.logo_url?<><img className="brandLogoImg" src={settings.logo_url} alt={brandName}/><div><b>{brandName}</b><small>Controle inteligente</small></div></>:<img className="officialAppLogo" src="/contaclaraai-logo.png" alt="ContaClaraAI"/>}</div></div><button className="mobileBackdrop" aria-label="Fechar menu" onClick={()=>setMobileMenuOpen(false)}/><aside><button className="mobileClose" aria-label="Fechar menu" onClick={()=>setMobileMenuOpen(false)}>×</button><div className="brand">{settings?.logo_url?<><img className="brandLogoImg" src={settings.logo_url} alt={brandName}/><div><b>{brandName}</b><small>Controle inteligente</small></div></>:<img className="officialAppLogo" src="/contaclaraai-logo.png" alt="ContaClaraAI"/>}</div><div className="control controlPicker orgPicker"><small>ORGANIZAÇÃO</small><select value={organization?.id||''} onChange={e=>switchOrganization(e.target.value)}>{organizations.map(o=><option value={o.id} key={o.id}>{o.nome}</option>)}</select><button className="controlManage" onClick={()=>{setPage('Organizações');setMobileMenuOpen(false)}}>Gerenciar organização</button></div><div className="control controlPicker"><small>CONTROLE ATUAL</small><select value={controle?.id||''} onChange={e=>switchControl(e.target.value)}>{controles.map(c=><option value={c.id} key={c.id}>{c.nome}</option>)}</select><button className="controlManage" onClick={()=>{setPage('Controles');setMobileMenuOpen(false)}}>Gerenciar controles</button></div><nav>{nav.map((n,i)=><button key={n} className={page===n?'active':''} onClick={()=>{setPage(n);setMobileMenuOpen(false)}}><Icon>{['⌂','▤','▣','◉','◇','♙','₿','▥','◎','◆','⚙'][i]}</Icon>{n}</button>)}</nav><div className="user"><div className="avatar">{(session.user.email||'U').slice(0,2).toUpperCase()}</div><div><b>{session.user.email}</b><button className="link" onClick={()=>supabase.auth.signOut()}>Sair</button></div></div></aside>
 {showOnboarding&&organization&&controle&&<Onboarding organization={organization} controle={controle} session={session} close={()=>{localStorage.setItem('ccai_onboarding_done','1');setShowOnboarding(false)}} finish={async({orgName,controlName,purpose})=>{const orgUpdate=await supabase.from('organizacoes').update({nome:orgName||organization.nome,updated_at:new Date().toISOString()}).eq('id',organization.id);const controlUpdate=await supabase.from('controles').update({nome:controlName||controle.nome,descricao:purpose||controle.descricao,updated_at:new Date().toISOString()}).eq('id',controle.id);if(orgUpdate.error||controlUpdate.error){setNotice(orgUpdate.error?.message||controlUpdate.error?.message);return false}localStorage.setItem('ccai_onboarding_done','1');setShowOnboarding(false);await loadData(controle.id,organization.id);return true}}/>}<main><header><div><h1>{page}</h1><p>{subtitle(page)}</p></div><div className="top"><select><option>Outubro 2026</option></select><button className="primary" onClick={()=>setPage('Nova despesa')}>＋ Nova despesa</button></div></header>{notice&&<div className="notice" onClick={()=>setNotice('')}>{notice} ×</div>}{dataLoading&&<div className="loading">Sincronizando com Supabase...</div>}
 {page==='Dashboard'&&<Dashboard total={total} paid={paid} pending={pending} rows={rows} byCat={byCat} open={r=>{setSelected(r);setPage('Detalhe')}} add={()=>setPage('Nova despesa')}/>} 
 {page==='Despesas'&&<Expenses rows={rows} query={query} setQuery={setQuery} open={r=>{setSelected(r);setPage('Detalhe')}} add={()=>setPage('Nova despesa')}/>} 
 {page==='Nova despesa'&&<ExpenseForm save={saveExpense} cancel={()=>setPage('Despesas')} categories={categories}/>} 
 {page==='Editar despesa'&&selected&&<EditExpenseForm r={selected} save={f=>updateExpense(selected,f)} cancel={()=>setPage('Detalhe')} categories={categories}/>} 
 {page==='Detalhe'&&selected&&<Detail r={selected} back={()=>setPage('Despesas')} edit={()=>setPage('Editar despesa')} remove={()=>removeExpense(selected)} openProof={()=>openProof(selected)} attachProof={file=>attachProof(selected,file)}/>} 
 {page==='Comprovantes'&&<Proofs rows={rows} openProof={openProof}/>} {page==='Importar WhatsApp'&&<WhatsApp saveExpense={saveExpense}/>} {page==='Categorias'&&<Categories byCat={byCat} categories={categories} saveCategory={saveCategory}/>} {page==='Pessoas'&&<People rows={rows}/>} {page==='Financeiro'&&<Finance rows={rows} budgets={budgets} recurrences={recurrences} splits={splits} categories={categories} saveBudget={saveBudget} saveRecurrence={saveRecurrence} toggleRecurrence={toggleRecurrence} saveSplit={saveSplit}/>} {page==='Conciliação Bancária'&&<BankReconciliation transactions={bankTransactions} rows={rows} categories={categories} controle={controle} organization={organization} session={session} reload={()=>loadData(controle?.id,organization?.id)} setNotice={setNotice}/>} {page==='Relatórios'&&<Reports rows={rows} organization={organization} controle={controle}/>} {page==='Controles'&&<Controls controles={controles} controle={controle} members={members} currentUser={session.user} switchControl={switchControl} createControl={createControl} updateControl={updateControl} inviteMember={inviteMember} changeMember={changeMember} removeMember={removeMember}/>} {page==='Organizações'&&<Organizations organizations={organizations} organization={organization} members={orgMembers} currentUser={session.user} switchOrganization={switchOrganization} createOrganization={createOrganization} inviteMember={inviteOrgMember} changeMember={changeOrgMember} removeMember={removeOrgMember}/>} {page==='Assinatura'&&<Billing organization={organization} subscription={subscription} usage={usage} currentUser={session.user} reload={()=>loadData(controle?.id,organization?.id)}/>} {page==='Configurações'&&<Settings settings={settings} save={saveSettings}/>} {page==='Admin SaaS'&&saasAdmin&&<SaasAdmin data={adminData} refresh={refreshAdmin}/>} 
 </main></div>
}
function dbToRow(r){return {id:r.id,date:r.data,desc:r.descricao,cat:r.categoria,value:Number(r.valor),payer:r.pagador||'',supplier:r.fornecedor||'',status:r.status,method:r.forma_pagamento||'',proof:r.comprovante_nome||'',proofPath:r.comprovante_path||'',notes:r.observacoes||'',pixTransactionId:r.pix_transacao_id||'',origem:r.origem||'manual',aiConfidence:r.ia_confianca||null}}
function safeName(n){return n.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9._-]/g,'_')}
function Auth({initialMode='login',back}){const [mode,setMode]=useState(initialMode);const [email,setEmail]=useState('');const [password,setPassword]=useState('');const [msg,setMsg]=useState('');const [busy,setBusy]=useState(false);async function go(e){e.preventDefault();setBusy(true);setMsg('');const res=mode==='login'?await supabase.auth.signInWithPassword({email,password}):await supabase.auth.signUp({email,password});if(res.error)setMsg(res.error.message);else if(mode==='signup'&&!res.data.session)setMsg('Cadastro criado. Verifique seu e-mail para confirmar a conta.');setBusy(false)}return <div className="authPage"><form className="authCard" onSubmit={go}>{back&&<button type="button" className="authBack" onClick={back}>← Voltar ao site</button>}<div className="authBrand"><img className="officialAuthLogo" src="/contaclaraai-logo.png" alt="ContaClaraAI"/></div><h2>{mode==='login'?'Entrar':'Criar conta'}</h2><p>Seus dados e comprovantes ficam protegidos por usuário.</p><Field l="E-mail"><input type="email" required value={email} onChange={e=>setEmail(e.target.value)}/></Field><Field l="Senha"><input type="password" required minLength="6" value={password} onChange={e=>setPassword(e.target.value)}/></Field>{msg&&<div className="notice">{msg}</div>}<button className="primary wide" disabled={busy}>{busy?'Aguarde...':mode==='login'?'Entrar':'Cadastrar'}</button><button type="button" className="ghost wide" onClick={()=>setMode(mode==='login'?'signup':'login')}>{mode==='login'?'Criar uma conta':'Já tenho uma conta'}</button></form></div>}

function Landing({onLogin,onSignup}){const scroll=id=>document.getElementById(id)?.scrollIntoView({behavior:'smooth'});return <div className="landing">
 <header className="landingNav"><button className="landingBrand" onClick={()=>scroll('inicio')}><img src="/contaclaraai-logo.png" alt="ContaClaraAI"/></button><nav><button onClick={()=>scroll('recursos')}>Recursos</button><button onClick={()=>scroll('como-funciona')}>Como funciona</button><button onClick={()=>scroll('precos')}>Preços</button></nav><div><button className="ghost" onClick={onLogin}>Entrar</button><button className="primary" onClick={()=>onSignup('free')}>Começar grátis</button></div></header>
 <main className="landingMain"><section className="hero" id="inicio"><div className="heroCopy"><span className="heroBadge">CONTROLE FINANCEIRO INTELIGENTE</span><h1>Despesas e comprovantes, <em>organizados com inteligência.</em></h1><p>Centralize gastos, comprovantes, PIX e prestações de contas. Importe conversas do WhatsApp, organize com IA e acompanhe tudo em um único lugar.</p><div className="heroActions"><button className="primary heroPrimary" onClick={()=>onSignup('free')}>Começar grátis →</button><button className="ghost heroGhost" onClick={()=>scroll('como-funciona')}>Ver como funciona</button></div><small>Sem cartão para começar • Configure seu primeiro controle em poucos minutos</small></div><div className="heroMock"><div className="mockTop"><i></i><i></i><i></i><b>ContaClaraAI</b></div><div className="mockBody"><aside><strong>C</strong><span>Dashboard</span><span>Despesas</span><span>Comprovantes</span><span>Relatórios</span></aside><div><small>Total de despesas</small><h3>R$ 1.893,59</h3><div className="mockChart"><b>Prestação de contas</b><i></i><i></i><i></i></div><div className="mockRows"><span>Fisioterapia <b>R$ 1.300,00</b></span><span>Cuidadora <b>R$ 300,00</b></span><span>Alimentação <b>R$ 208,59</b></span></div></div></div></div></section>
 <section className="pain"><div><span>COMPROVANTES PERDIDOS?</span><h2>Chega de procurar despesas em conversas, planilhas e pastas.</h2><p>O ContaClaraAI transforma um processo fragmentado em um fluxo simples: registrar, comprovar e entender.</p></div><div className="painGrid"><article><b>01</b><h3>Registre</h3><p>Lance despesas manualmente ou importe conversas exportadas do WhatsApp.</p></article><article><b>02</b><h3>Comprove</h3><p>Centralize recibos, comprovantes PIX, PDFs e imagens junto ao lançamento.</p></article><article><b>03</b><h3>Entenda</h3><p>Acompanhe categorias, responsáveis, pendências e gere prestações de contas.</p></article></div></section>
 <section className="features" id="recursos"><div className="sectionIntro"><span>RECURSOS</span><h2>Do gasto ao relatório, sem perder o contexto.</h2></div><div className="featureGrid"><article><i>◉</i><h3>Importação do WhatsApp</h3><p>Identifique despesas em conversas e reduza o trabalho de digitação.</p></article><article><i>✦</i><h3>IA para comprovantes</h3><p>Extraia valor, data, favorecido e categoria com revisão humana.</p></article><article><i>▣</i><h3>Comprovantes centralizados</h3><p>Tenha documento e lançamento financeiro sempre vinculados.</p></article><article><i>▥</i><h3>Prestação de contas</h3><p>Gere uma visão consolidada e pronta para compartilhar.</p></article><article><i>♙</i><h3>Controle compartilhado</h3><p>Convide pessoas e organize responsabilidades no mesmo workspace.</p></article><article><i>◎</i><h3>Gestão financeira</h3><p>Orçamentos, recorrências, rateios e pendências em um só painel.</p></article></div></section>
 <section className="how" id="como-funciona"><div className="sectionIntro"><span>COMECE AGORA</span><h2>Da criação da conta ao primeiro controle em 5 passos.</h2></div><div className="steps"><article><b>1</b><div><h3>Crie sua conta</h3><p>Informe e-mail e senha e confirme seu acesso.</p></div></article><article><b>2</b><div><h3>Configure seu workspace</h3><p>Dê um nome ao espaço onde seus controles ficarão organizados.</p></div></article><article><b>3</b><div><h3>Crie seu primeiro controle</h3><p>Família, cuidados, pequeno negócio, projeto ou outra finalidade.</p></div></article><article><b>4</b><div><h3>Registre ou importe</h3><p>Adicione a primeira despesa ou importe uma conversa do WhatsApp.</p></div></article><article><b>5</b><div><h3>Acompanhe e compartilhe</h3><p>Use o dashboard e gere sua prestação de contas.</p></div></article></div><button className="primary heroPrimary" onClick={()=>onSignup('free')}>Criar minha conta grátis</button></section>
 <section className="pricing" id="precos"><div className="sectionIntro"><span>PLANOS</span><h2>Comece grátis. Evolua quando precisar.</h2><p>Planos mensais, sem fidelidade.</p></div><div className="landingPricing"><Plan name="Free" price="R$ 0" items={['1 controle','2 membros','10 análises IA/mês','100 MB de arquivos']} action="Começar grátis" click={()=>onSignup('free')}/><Plan featured name="Plus" price="R$ 29,90" items={['5 controles','10 membros','150 análises IA/mês','2 GB de arquivos','Prestação de contas']} action="Assinar Plus" click={()=>onSignup('plus')}/><Plan name="Pro" price="R$ 69,90" items={['Controles ampliados','30 membros','600 análises IA/mês','10 GB de arquivos','Auditoria e identidade']} action="Assinar Pro" click={()=>onSignup('pro')}/></div></section>
 <section className="landingCta"><h2>Organize hoje o que você não quer procurar amanhã.</h2><p>Crie sua conta e tenha seu primeiro controle funcionando em poucos minutos.</p><button className="primary heroPrimary" onClick={()=>onSignup('free')}>Começar gratuitamente →</button></section></main>
 <footer className="landingFooter"><b>ContaClaraAI</b><span>Despesas e comprovantes, organizados com inteligência.</span><small>© 2026 ContaClaraAI</small></footer>
 </div>}
function Plan({name,price,items,action,click,featured}){return <article className={`landingPlan ${featured?'featured':''}`}>{featured&&<span className="popular">MAIS ESCOLHIDO</span>}<h3>{name}</h3><div className="landingPrice"><strong>{price}</strong><small>/mês</small></div><ul>{items.map(x=><li key={x}>✓ {x}</li>)}</ul><button className={featured?'primary':'ghost'} onClick={click}>{action}</button></article>}
function Onboarding({organization,controle,close,finish}){const [step,setStep]=useState(0),[orgName,setOrgName]=useState(organization.nome==='Minha organização'?'':organization.nome),[controlName,setControlName]=useState(controle.nome==='Meu controle'?'':controle.nome),[purpose,setPurpose]=useState('Despesas familiares'),[busy,setBusy]=useState(false);const next=()=>setStep(x=>Math.min(2,x+1));async function done(){setBusy(true);const ok=await finish({orgName:orgName||'Meu workspace',controlName:controlName||purpose,purpose});setBusy(false);if(ok)close()}return <div className="onboardingBackdrop"><div className="onboarding"><button className="onboardingSkip" onClick={close}>Pular por agora</button><div className="onboardingProgress"><i className={step>=0?'on':''}></i><i className={step>=1?'on':''}></i><i className={step>=2?'on':''}></i></div>{step===0&&<><span className="heroBadge">BEM-VINDO AO CONTACLARAAI</span><h2>Vamos deixar seu espaço pronto.</h2><p>Primeiro, dê um nome ao seu workspace. Ele agrupa seus controles e pessoas.</p><Field l="Nome do workspace"><input autoFocus value={orgName} onChange={e=>setOrgName(e.target.value)} placeholder="Ex.: Família Oliveira"/></Field><button className="primary wide" onClick={next}>Continuar →</button></>}{step===1&&<><span className="heroBadge">PASSO 2 DE 3</span><h2>O que você quer organizar?</h2><p>Isso nos ajuda a preparar seu primeiro controle.</p><div className="purposeGrid">{['Despesas familiares','Cuidados de familiar','Pequeno negócio','Projeto / Grupo','Outro'].map(x=><button className={purpose===x?'active':''} onClick={()=>setPurpose(x)} key={x}>{x}</button>)}</div><button className="primary wide" onClick={next}>Continuar →</button></>}{step===2&&<><span className="heroBadge">PASSO 3 DE 3</span><h2>Nomeie seu primeiro controle.</h2><p>Você poderá criar outros controles depois.</p><Field l="Nome do controle"><input autoFocus value={controlName} onChange={e=>setControlName(e.target.value)} placeholder={purpose}/></Field><button className="primary wide" disabled={busy} onClick={done}>{busy?'Configurando...':'Entrar no ContaClaraAI →'}</button></>}</div></div>}

function subtitle(p){return ({Dashboard:'Acompanhe os gastos do controle em tempo real.',Despesas:'Visualize e gerencie todas as despesas.','Comprovantes':'Centralize os documentos vinculados aos lançamentos.','Importar WhatsApp':'Identifique possíveis despesas a partir de uma conversa exportada.',Categorias:'Organize os lançamentos por finalidade.',Pessoas:'Acompanhe quem realizou os pagamentos.',Financeiro:'Orçamentos, recorrências, rateios e pendências do controle.','Conciliação Bancária':'Importe OFX/CSV e concilie o extrato com suas despesas usando IA.',Relatórios:'Consolide a prestação de contas do período.',Controles:'Crie controles independentes dentro do workspace.',Organizações:'Gerencie workspaces, membros e permissões do SaaS.',Assinatura:'Plano, limites, trial e consumo do seu workspace.',Configurações:'Personalize a identidade e os dados do sistema.','Admin SaaS':'Clientes, workspaces, receita, assinaturas e consumo da plataforma.','Nova despesa':'Registre uma nova despesa e seu comprovante.',Detalhe:'Confira todos os dados do lançamento.'})[p]||''}
function Cards({total,paid,pending,count}){return <div className="cards"><Card t="Total de despesas" v={money(total)} icon="▣"/><Card t="Pagas" v={money(paid)} icon="✓"/><Card t="A pagar" v={money(pending)} icon="◷"/><Card t="Lançamentos" v={count} icon="▤"/></div>}
function Card({t,v,icon}){return <div className="card metric"><div className="metricIcon">{icon}</div><div><small>{t}</small><strong>{v}</strong></div></div>}
function Dashboard({total,paid,pending,rows,byCat,open,add}){return <><Cards total={total} paid={paid} pending={pending} count={rows.length}/><div className="grid2"><div className="card"><h3>Despesas por categoria</h3><div className="chart"><div className="donut"><b>{money(total)}</b><small>Total</small></div><div className="legend">{byCat.slice(0,5).map(([c,v])=><div key={c}><span className="dot"></span><em>{c}</em><b>{money(v)}</b></div>)}</div></div></div><div className="card"><h3>Quem mais pagou</h3><div className="payer"><b>Thais</b><div><i style={{width:'94%'}}></i></div><strong>{money(paid)}</strong></div><div className="payer"><b>Outros</b><div><i style={{width:'4%'}}></i></div><strong>R$ 0,00</strong></div></div></div><div className="card tableCard"><div className="sectionTitle"><h3>Últimas despesas</h3><button className="primary" onClick={add}>＋ Nova despesa</button></div><Table rows={rows.slice(0,5)} open={open}/></div></>}
function Table({rows,open}){return <div className="table"><div className="tr th"><span>Data</span><span>Descrição</span><span>Categoria</span><span>Valor</span><span>Quem pagou</span><span>Status</span></div>{rows.map(r=><button className="tr" key={r.id} onClick={()=>open?.(r)}><span>{r.date.split('-').reverse().join('/')}</span><span><b>{r.desc}</b><small>{r.supplier}</small></span><span><label>{r.cat}</label></span><span><b>{money(r.value)}</b></span><span>{r.payer}</span><span><mark>● {r.status}</mark></span></button>)}</div>}
function Expenses({rows,query,setQuery,open,add}){const f=rows.filter(r=>(r.desc+r.cat+r.supplier).toLowerCase().includes(query.toLowerCase()));return <div className="card"><div className="toolbar"><input placeholder="Buscar descrição, fornecedor, categoria..." value={query} onChange={e=>setQuery(e.target.value)}/><button className="primary" onClick={add}>＋ Nova despesa</button></div><Table rows={f} open={open}/></div>}
function ExpenseForm({save,cancel,categories}){const [file,setFile]=useState(null); const [f,setF]=useState({desc:'',cat:'Fisioterapia',value:'',date:'2026-10-05',payer:'Thais',supplier:'',status:'Pago',method:'PIX',proof:'',notes:''}); const upd=(k,v)=>setF({...f,[k]:v});return <div className="formgrid"><div className="card"><h3>Dados da despesa</h3><div className="fields"><Field l="Descrição *"><input value={f.desc} onChange={e=>upd('desc',e.target.value)} placeholder="Ex.: 10 sessões de fisioterapia"/></Field><Field l="Categoria *"><select value={f.cat} onChange={e=>upd('cat',e.target.value)}>{(categories?.filter(c=>c.ativo).map(c=>c.nome)||defaultCats).map(c=><option key={c}>{c}</option>)}</select></Field><Field l="Valor *"><input value={f.value} onChange={e=>upd('value',e.target.value.replace(',','.'))} placeholder="1300,00"/></Field><Field l="Data *"><input type="date" value={f.date} onChange={e=>upd('date',e.target.value)}/></Field><Field l="Quem pagou?"><input value={f.payer} onChange={e=>upd('payer',e.target.value)}/></Field><Field l="Fornecedor / Recebedor"><input value={f.supplier} onChange={e=>upd('supplier',e.target.value)}/></Field><Field l="Forma de pagamento"><select value={f.method} onChange={e=>upd('method',e.target.value)}><option>PIX</option><option>Cartão</option><option>Dinheiro</option><option>Transferência</option></select></Field><Field l="Status"><select value={f.status} onChange={e=>upd('status',e.target.value)}><option>Pago</option><option>Pendente</option></select></Field></div><Field l="Observações"><textarea value={f.notes} onChange={e=>upd('notes',e.target.value)}/></Field></div><div className="card"><h3>Comprovante</h3><div className="upload"><b>⇧</b><strong>Selecione um comprovante</strong><small>PDF, JPG ou PNG</small><input type="file" accept=".pdf,image/*" onChange={e=>{const x=e.target.files?.[0]||null;setFile(x);upd('proof',x?.name||'')}}/></div>{f.proof&&<div className="file">📄 {f.proof}</div>}<button className="primary wide" disabled={!f.desc||!f.value} onClick={()=>save({...f,value:Number(f.value)},file)}>Salvar despesa</button><button className="ghost wide" onClick={cancel}>Cancelar</button></div></div>}
function Field({l,children}){return <label className="field"><span>{l}</span>{children}</label>}
function EditExpenseForm({r,save,cancel,categories}){const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [f,setF]=useState({desc:r.desc||'',cat:r.cat||'',value:String(r.value??''),date:r.date||'',payer:r.payer||'',supplier:r.supplier||'',status:r.status||'Pago',method:r.method||'PIX',notes:r.notes||''});const upd=(k,v)=>setF({...f,[k]:v});async function submit(e){e.preventDefault();setError('');if(!f.desc.trim()){setError('Informe a descrição da despesa.');return}if(!f.cat){setError('Selecione uma categoria.');return}if(!f.date){setError('Informe a data.');return}if(!Number(f.value)||Number(f.value)<=0){setError('Informe um valor maior que zero.');return}setBusy(true);const ok=await save({...f,value:Number(f.value)});if(!ok)setBusy(false)}return <form className="formgrid" onSubmit={submit}><div className="card"><div className="detailActions"><button type="button" className="link" onClick={cancel}>← Cancelar</button><span className="editBadge">Editando lançamento</span></div><h3>Editar despesa</h3>{error&&<div className="notice">{error}</div>}<div className="fields"><Field l="Descrição *"><input value={f.desc} onChange={e=>upd('desc',e.target.value)}/></Field><Field l="Categoria *"><select value={f.cat} onChange={e=>upd('cat',e.target.value)}>{(categories?.filter(c=>c.ativo||c.nome===r.cat).map(c=>c.nome)||defaultCats).map(c=><option key={c}>{c}</option>)}</select></Field><Field l="Valor *"><input inputMode="decimal" value={f.value} onChange={e=>upd('value',e.target.value.replace(',','.'))}/></Field><Field l="Data *"><input type="date" value={f.date} onChange={e=>upd('date',e.target.value)}/></Field><Field l="Quem pagou?"><input value={f.payer} onChange={e=>upd('payer',e.target.value)}/></Field><Field l="Fornecedor / Recebedor"><input value={f.supplier} onChange={e=>upd('supplier',e.target.value)}/></Field><Field l="Forma de pagamento"><select value={f.method} onChange={e=>upd('method',e.target.value)}><option>PIX</option><option>Cartão</option><option>Dinheiro</option><option>Transferência</option></select></Field><Field l="Status"><select value={f.status} onChange={e=>upd('status',e.target.value)}><option>Pago</option><option>Pendente</option></select></Field></div><Field l="Observações"><textarea value={f.notes} onChange={e=>upd('notes',e.target.value)}/></Field><div className="editFormActions"><button type="button" className="ghost" onClick={cancel}>Cancelar</button><button className="primary" disabled={busy}>{busy?'Salvando...':'Salvar alterações'}</button></div></div><div className="card editProofInfo"><h3>Comprovante</h3><p>O comprovante não é alterado ao editar os dados financeiros.</p>{r.proof?<div className="file">📄 {r.proof}</div>:<div className="empty">Nenhum comprovante anexado.</div>}<small>Para anexar ou substituir o documento, volte ao detalhe da despesa e utilize o card Comprovante.</small></div></form>}
function Detail({r,back,edit,remove,openProof,attachProof}){const [file,setFile]=useState(null);return <div className="formgrid"><div className="card"><div className="detailActions"><button className="link" onClick={back}>← Voltar</button><button className="primary" onClick={edit}>✎ Editar despesa</button></div><h3>Informações da despesa</h3><dl>{[['Descrição',r.desc],['Categoria',r.cat],['Valor',money(r.value)],['Data',r.date.split('-').reverse().join('/')],['Quem pagou',r.payer],['Fornecedor',r.supplier],['Forma de pagamento',r.method],['Status',r.status]].map(x=><div key={x[0]}><dt>{x[0]}</dt><dd>{x[1]}</dd></div>)}</dl><button className="danger" onClick={remove}>Excluir lançamento</button></div><div className="card"><h3>Comprovante</h3>{r.proof?<><div className="proofPreview"><div>COMPROVANTE</div><b>{money(r.value)}</b><small>{r.supplier}</small><small>{r.date}</small><p>✓ Documento anexado</p><button className="primary wide" onClick={openProof}>Abrir comprovante</button></div><label className="replaceProof">Substituir comprovante<input type="file" accept=".pdf,image/jpeg,image/png,image/webp" onChange={e=>{const f=e.target.files?.[0];if(f)attachProof(f)}}/></label></>:<div className="proofUploadBox"><div className="empty">Nenhum comprovante anexado.</div><label className="upload compactUpload"><b>⇧</b><strong>{file?file.name:'Selecionar comprovante'}</strong><small>PDF, JPG, PNG ou WEBP · máximo 10 MB</small><input type="file" accept=".pdf,image/jpeg,image/png,image/webp" onChange={e=>setFile(e.target.files?.[0]||null)}/></label><button className="primary wide" disabled={!file} onClick={()=>attachProof(file)}>Enviar comprovante</button></div>}</div></div>}
function Proofs({rows,openProof}){return <div className="proofgrid">{rows.map(r=><button className="card proof" key={r.id} onClick={()=>r.proofPath&&openProof(r)}><div className="doc">PDF</div><div><b>{r.proof||'Sem arquivo anexado'}</b><small>{r.desc}</small><strong>{money(r.value)}</strong></div></button>)}</div>}
function parseWhatsApp(text){
 const raw=text.replace(/\r/g,'').split('\n'); const msgs=[]; let cur=null;
 const re=/^\[(\d{1,2})\/(\d{1,2})\/(\d{2,4}),\s*(\d{1,2}):(\d{2})(?::(\d{2}))?\s*(AM|PM)?\]\s*(?:-\s*)?(?:([^:]+):\s*)?(.*)$/i;
 for(const line of raw){const m=line.match(re);if(m){if(cur)msgs.push(cur);let [,mo,da,yr,hh,mi,ss,ap,author,body]=m;let h=Number(hh);if(ap){if(ap.toUpperCase()==='PM'&&h<12)h+=12;if(ap.toUpperCase()==='AM'&&h===12)h=0}const y=Number(yr)<100?2000+Number(yr):Number(yr);cur={date:`${y}-${String(mo).padStart(2,'0')}-${String(da).padStart(2,'0')}`,time:`${String(h).padStart(2,'0')}:${mi}`,author:(author||'Sistema').trim(),text:(body||'').trim()}}else if(cur&&line.trim())cur.text+='\n'+line.trim()}if(cur)msgs.push(cur);return msgs
}
function brMoney(t){const m=t.match(/R\$\s*([\d.]+,\d{2})|(?:total\s*)?([\d.]+[,.]\d{2})/i);if(!m)return null;const v=(m[1]||m[2]).replace(/\./g,'').replace(',','.');const n=Number(v);return Number.isFinite(n)?n:null}
function classifyText(t){const x=t.toLowerCase();if(/fisioter/.test(x))return 'Fisioterapia';if(/cuidador|cuidadora/.test(x))return 'Cuidadora';if(/dieta|papinha|enteral/.test(x))return 'Dieta / Alimentação';if(/algod|álcool|alcool|luva|higiene|medic/.test(x))return 'Medicamentos / Higiene';if(/almofada|cadeira|equip/.test(x))return 'Equipamentos';return 'Outros'}
function analyzeWhatsApp(msgs){const out=[];const ignored=/criptografia|criou o grupo|mudou o nome|figurinha|mensagem apagada|obrigado|blz|fechado|vai mandando|vou criar um controle/i;for(let i=0;i<msgs.length;i++){const m=msgs[i];if(ignored.test(m.text))continue;const window=msgs.slice(i,Math.min(msgs.length,i+4)).filter(x=>x.date===m.date);const context=window.map(x=>x.text).join(' ');const proof=(context.match(/([\w.-]+\.pdf)/i)||[])[1]||'';const amount=brMoney(context);const meaningful=/fisioter|cuidador|cuidadora|dieta|papinha|algod|álcool|alcool|luva|higiene|medic|almofada|cadeira|equip|R\$/i.test(context);if(!meaningful&&!proof)continue;
 let desc='';for(const x of window){const clean=x.text.replace(/\[Encaminhada\]|<documento omitido>|<imagem ocultada>|\[Documento\]|\[Imagem\]/gi,'').replace(/[\w.-]+\.pdf/ig,'').trim();if(clean&&!/^segue o comprovante/i.test(clean)&&!/^R\$/i.test(clean)&&clean.length>3){desc=clean.split('\n')[0];if(/pagamento|fisioter|papinha|algod|dieta|almofada|equip/i.test(clean))break}}
 if(!desc)desc=proof?'Comprovante importado':'Despesa identificada';const cat=classifyText(context);let confidence=55+(proof?20:0)+(amount?15:0)+(cat!=='Outros'?10:0);confidence=Math.min(99,confidence);const key=[m.date,proof,amount,cat].join('|');if(out.some(x=>x.key===key))continue;out.push({key,date:m.date,desc,cat,value:amount||'',payer:m.author==='Sistema'?'':m.author,supplier:'',status:'Pago',method:proof?'PIX':'',proof,notes:`Importado do WhatsApp. Contexto: ${context.slice(0,700)}`,confidence,selected:!!amount})}return out}
function normalizeZipName(name){return name.replace(/\\/g,'/').split('/').pop()||name}
async function expandWhatsAppSelection(selected){
 const input=Array.from(selected||[]); const zipFile=input.find(f=>f.name.toLowerCase().endsWith('.zip'));
 if(!zipFile)return {files:input,zipName:'',zipEntries:0};
 const zip=await JSZip.loadAsync(zipFile); const extracted=[]; let entries=0;
 for(const [path,entry] of Object.entries(zip.files)){
  if(entry.dir||path.startsWith('__MACOSX/')||path.split('/').some(x=>x.startsWith('.')))continue;
  const name=normalizeZipName(path); if(!name)continue; entries++;
  const blob=await entry.async('blob'); extracted.push(new File([blob],name,{type:guessMime(name),lastModified:Date.now()}));
 }
 return {files:[...input.filter(f=>f!==zipFile),...extracted],zipName:zipFile.name,zipEntries:entries};
}
function guessMime(name){const ext=name.toLowerCase().split('.').pop();return ({txt:'text/plain',pdf:'application/pdf',jpg:'image/jpeg',jpeg:'image/jpeg',png:'image/png',webp:'image/webp',heic:'image/heic',mp4:'video/mp4',opus:'audio/ogg',ogg:'audio/ogg'}[ext]||'application/octet-stream')}
function WhatsApp({saveExpense}){const [files,setFiles]=useState([]);const [step,setStep]=useState(1);const [messages,setMessages]=useState([]);const [candidates,setCandidates]=useState([]);const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [zipInfo,setZipInfo]=useState(null);const [aiBusy,setAiBusy]=useState(null);const txt=files.find(f=>f.name.toLowerCase().endsWith('.txt'));
 async function choose(e){setBusy(true);setError('');try{const result=await expandWhatsAppSelection(e.target.files);setFiles(result.files);setZipInfo(result.zipName?{name:result.zipName,entries:result.zipEntries}:null);setStep(1)}catch(err){setFiles([]);setZipInfo(null);setError('Não foi possível abrir o ZIP: '+err.message)}finally{setBusy(false);e.target.value=''}}
 async function analyze(){if(!txt){setError('O ZIP precisa conter o arquivo .txt exportado pelo WhatsApp.');return}setBusy(true);setError('');try{const text=await txt.text();const parsed=parseWhatsApp(text);setMessages(parsed);setCandidates(analyzeWhatsApp(parsed));setStep(2)}catch(e){setError('Não foi possível ler a conversa: '+e.message)}finally{setBusy(false)}}
 function upd(i,k,v){setCandidates(candidates.map((c,n)=>n===i?{...c,[k]:v}:c))}
 async function analyzeWithAI(i){const c=candidates[i];const media=files.find(f=>c.proof&&normalizeZipName(f.name).toLowerCase()===normalizeZipName(c.proof).toLowerCase())||null;if(!media){setError('Para análise por IA, o comprovante precisa estar presente no ZIP ou selecionado manualmente.');return}if(media.size>10*1024*1024){setError('O arquivo para IA deve ter no máximo 10 MB.');return}setAiBusy(i);setError('');try{const token=(await supabase.auth.getSession()).data.session?.access_token;if(!token)throw new Error('Sessão expirada. Entre novamente.');const fd=new FormData();fd.append('file',media);fd.append('context',c.notes.replace('Importado do WhatsApp. Contexto: ',''));fd.append('categories',JSON.stringify(cats));const res=await fetch('/api/ai/extract',{method:'POST',headers:{Authorization:`Bearer ${token}`},body:fd});const body=await res.json();if(!res.ok)throw new Error(body.error||'Falha na análise por IA.');const a=body.data||{};setCandidates(prev=>prev.map((x,n)=>n===i?{...x,desc:a.descricao||x.desc,cat:a.categoria&&cats.includes(a.categoria)?a.categoria:x.cat,value:a.valor??x.value,date:a.data||x.date,payer:a.pagador||x.payer,supplier:a.recebedor||x.supplier,method:a.forma_pagamento||x.method,pixTransactionId:a.pix_transacao_id||'',aiConfidence:a.confianca||x.confidence,aiData:a,confidence:a.confianca||x.confidence,selected:!!(a.valor||x.value),aiAnalyzed:true}:x));}catch(e){setError(e.message)}finally{setAiBusy(null)}}
 async function confirm(){const chosen=candidates.filter(c=>c.selected);if(!chosen.length){setError('Selecione pelo menos um lançamento para importar.');return}const invalid=chosen.find(c=>!Number(c.value)||Number(c.value)<=0);if(invalid){setError('Informe um valor válido para todos os lançamentos selecionados.');return}setBusy(true);setError('');try{for(const c of chosen){const media=files.find(f=>c.proof&&normalizeZipName(f.name).toLowerCase()===normalizeZipName(c.proof).toLowerCase())||null;const ok=await saveExpense({...c,value:Number(c.value),origem:'whatsapp',aiConfidence:c.aiConfidence||null,aiData:c.aiData||null},media,true);if(!ok)throw new Error('Falha ao salvar um dos lançamentos.')}setStep(3)}catch(e){setError(e.message)}finally{setBusy(false)}}
 const mediaCount=files.filter(f=>!f.name.toLowerCase().endsWith('.txt')).length;
 return <div className="card wa"><div className="steps"><b className={step===1?'current':''}>1 Upload do arquivo</b><b className={step===2?'current':''}>2 Análise das mensagens</b><b className={step===3?'current':''}>3 Conferência</b></div>{step===1&&<><div className="upload big"><b>◉</b><strong>Importar exportação do WhatsApp</strong><small>Selecione o arquivo .zip exportado pelo WhatsApp com mídia. Também aceitamos .txt, PDFs e imagens selecionados manualmente.</small><input type="file" multiple accept=".zip,.txt,.pdf,image/*" onChange={choose}/>{busy&&<small>Extraindo arquivos...</small>}</div>{files.length>0&&<div className="analysis"><h3>Arquivo pronto para análise</h3>{zipInfo&&<p><b>{zipInfo.name}</b> · {zipInfo.entries} arquivo(s) extraído(s) do ZIP</p>}<p><b>{txt?.name||'Nenhum .txt encontrado'}</b> · {mediaCount} arquivo(s) de mídia</p>{!txt&&<div className="notice">Não encontramos um arquivo .txt dentro da exportação. Exporte a conversa do WhatsApp incluindo a conversa e tente novamente.</div>}<button className="primary" disabled={busy||!txt} onClick={analyze}>{busy?'Processando...':'Analisar conversa'}</button></div>}</>}
 {step===2&&<div className="analysis wideAnalysis"><div className="reviewHead"><div><h3>Possíveis despesas encontradas</h3><p>{messages.length} mensagens lidas · {candidates.length} candidatos · {mediaCount} mídia(s) disponível(is). Revise antes de gravar.</p></div><button className="ghost" onClick={()=>setStep(1)}>Trocar arquivo</button></div>{candidates.length===0?<div className="empty">Nenhuma despesa foi identificada automaticamente.</div>:candidates.map((c,i)=><div className={'candidate '+(c.selected?'selected':'')} key={c.key}><input className="check" type="checkbox" checked={c.selected} onChange={e=>upd(i,'selected',e.target.checked)}/><div className="candidateBody"><div className="candidateTop"><input value={c.desc} onChange={e=>upd(i,'desc',e.target.value)}/><mark>Confiança: {c.confidence}%</mark></div><div className="candidateFields"><Field l="Data"><input type="date" value={c.date} onChange={e=>upd(i,'date',e.target.value)}/></Field><Field l="Categoria"><select value={c.cat} onChange={e=>upd(i,'cat',e.target.value)}>{cats.map(x=><option key={x}>{x}</option>)}</select></Field><Field l="Valor"><input inputMode="decimal" placeholder="Obrigatório" value={c.value} onChange={e=>upd(i,'value',e.target.value.replace(',','.'))}/></Field><Field l="Pagador"><input value={c.payer} onChange={e=>upd(i,'payer',e.target.value)}/></Field></div><div className="aiActions">{c.proof&&files.some(f=>normalizeZipName(f.name).toLowerCase()===normalizeZipName(c.proof).toLowerCase())&&<button type="button" className="ghost aiButton" disabled={aiBusy!==null} onClick={()=>analyzeWithAI(i)}>{aiBusy===i?'✦ Analisando...':'✦ Analisar comprovante com IA'}</button>}{c.aiAnalyzed&&<span className="aiBadge">IA aplicada · {c.aiConfidence||c.confidence}%</span>}{c.pixTransactionId&&<span className="pixId">PIX: {c.pixTransactionId}</span>}</div>{c.proof&&<div className="matchedProof">📄 {c.proof} {files.some(f=>normalizeZipName(f.name).toLowerCase()===normalizeZipName(c.proof).toLowerCase())?<span>arquivo encontrado no ZIP</span>:<em>referência no chat; arquivo não encontrado</em>}</div>}<details><summary>Ver contexto detectado</summary><pre>{c.notes.replace('Importado do WhatsApp. Contexto: ','')}</pre></details></div></div>)}<div className="reviewActions"><button className="primary" disabled={busy} onClick={confirm}>{busy?'Importando...':`Importar ${candidates.filter(c=>c.selected).length} selecionado(s)`}</button></div></div>}
 {step===3&&<div className="successImport"><div className="successIcon">✓</div><h3>Importação concluída</h3><p>Os lançamentos confirmados foram gravados no Supabase. Comprovantes encontrados dentro do ZIP foram enviados ao Storage privado.</p><button className="primary" onClick={()=>{setStep(1);setFiles([]);setMessages([]);setCandidates([]);setZipInfo(null)}}>Nova importação</button></div>}{error&&<div className="notice">{error}</div>}</div>}

function Categories({byCat,categories,saveCategory}){const [editing,setEditing]=useState(null);const [show,setShow]=useState(false);const empty={nome:'',descricao:'',ativo:true};function edit(c){setEditing({...c});setShow(true)}function create(){setEditing(empty);setShow(true)}async function submit(e){e.preventDefault();if(!editing.nome.trim())return;if(await saveCategory(editing)){setShow(false);setEditing(null)}}return <><div className="sectionTitle categoryHeader"><div><h3>Categorias</h3><p>Cadastre, edite ou inative as categorias usadas nos lançamentos.</p></div><button className="primary" onClick={create}>＋ Nova categoria</button></div><div className="categoryGrid">{categories.map(c=><div className={`card category categoryManage ${!c.ativo?'inactive':''}`} key={c.id}><div className="catIcon">◇</div><div className="categoryInfo"><b>{c.nome}</b><small>{c.descricao||'Sem descrição'}</small><small>Total lançado: {money(byCat.find(x=>x[0]===c.nome)?.[1]||0)}</small><span className={c.ativo?'statusOn':'statusOff'}>{c.ativo?'Ativa':'Inativa'}</span></div><button className="ghost" onClick={()=>edit(c)}>Editar</button></div>)}</div>{show&&<div className="modalBackdrop" onMouseDown={e=>{if(e.target===e.currentTarget)setShow(false)}}><form className="modalCard" onSubmit={submit}><div className="sectionTitle"><h3>{editing.id?'Editar categoria':'Nova categoria'}</h3><button type="button" className="link" onClick={()=>setShow(false)}>✕</button></div><Field l="Nome *"><input autoFocus value={editing.nome} onChange={e=>setEditing({...editing,nome:e.target.value})}/></Field><Field l="Descrição"><textarea value={editing.descricao||''} onChange={e=>setEditing({...editing,descricao:e.target.value})}/></Field><label className="toggleLine"><input type="checkbox" checked={editing.ativo} onChange={e=>setEditing({...editing,ativo:e.target.checked})}/><span>Categoria ativa</span></label><div className="modalActions"><button type="button" className="ghost" onClick={()=>setShow(false)}>Cancelar</button><button className="primary" disabled={!editing.nome.trim()}>Salvar categoria</button></div></form></div>}</>}
function Controls({controles,controle,members,currentUser,switchControl,createControl,updateControl,inviteMember,changeMember,removeMember}){const [showNew,setShowNew]=useState(false);const [newControl,setNewControl]=useState({nome:'',descricao:''});const [edit,setEdit]=useState({nome:controle?.nome||'',descricao:controle?.descricao||''});const [email,setEmail]=useState('');const [role,setRole]=useState('editor');useEffect(()=>setEdit({nome:controle?.nome||'',descricao:controle?.descricao||''}),[controle?.id,controle?.nome,controle?.descricao]);const owner=controle?.user_id===currentUser.id;async function addControl(e){e.preventDefault();if(await createControl(newControl)){setShowNew(false);setNewControl({nome:'',descricao:''})}}async function addMember(e){e.preventDefault();if(await inviteMember(email,role))setEmail('')}return <><div className="sectionTitle controlHeader"><div><h3>Meus controles</h3><p>Separe despesas por finalidade e compartilhe cada controle com as pessoas certas.</p></div><button className="primary" onClick={()=>setShowNew(true)}>＋ Novo controle</button></div><div className="controlCards">{controles.map(c=><button key={c.id} className={'controlCard '+(c.id===controle?.id?'selected':'')} onClick={()=>switchControl(c.id)}><span>{c.user_id===currentUser.id?'Proprietário':'Compartilhado'}</span><b>{c.nome}</b><small>{c.descricao||'Sem descrição'}</small></button>)}</div>{controle&&<div className="grid2 controlAdmin"><div className="card"><h3>Dados do controle</h3><p className="muted">{owner?'Você é o proprietário deste controle.':'Este controle foi compartilhado com você.'}</p><Field l="Nome"><input value={edit.nome} disabled={!owner} onChange={e=>setEdit({...edit,nome:e.target.value})}/></Field><Field l="Descrição"><textarea value={edit.descricao} disabled={!owner} onChange={e=>setEdit({...edit,descricao:e.target.value})}/></Field>{owner&&<button className="primary" onClick={()=>updateControl(edit)}>Salvar alterações</button>}</div><div className="card"><h3>Membros e compartilhamento</h3><p className="muted">Administrador e Editor podem alterar despesas. Visualizador possui acesso somente para consulta.</p>{owner&&<form className="inviteForm" onSubmit={addMember}><Field l="E-mail"><input type="email" required placeholder="pessoa@email.com" value={email} onChange={e=>setEmail(e.target.value)}/></Field><Field l="Permissão"><select value={role} onChange={e=>setRole(e.target.value)}><option value="administrador">Administrador</option><option value="editor">Editor</option><option value="visualizador">Visualizador</option></select></Field><button className="primary">Convidar</button></form>}<div className="memberList"><div className="memberRow ownerRow"><div className="avatar">{(currentUser.email||'EU').slice(0,2).toUpperCase()}</div><div><b>{owner?currentUser.email:'Proprietário do controle'}</b><small>Proprietário</small></div></div>{members.map(m=><div className="memberRow" key={m.id}><div className="avatar">{m.email.slice(0,2).toUpperCase()}</div><div><b>{m.email}</b><small>{m.status==='ativo'?'Acesso ativo':'Convite pendente'}</small></div>{owner?<select value={m.papel} onChange={e=>changeMember(m.id,e.target.value)}><option value="administrador">Administrador</option><option value="editor">Editor</option><option value="visualizador">Visualizador</option></select>:<span className="roleBadge">{m.papel}</span>}{owner&&<button className="memberRemove" onClick={()=>removeMember(m.id)}>Remover</button>}</div>)}</div></div></div>}{showNew&&<div className="modalBackdrop" onMouseDown={e=>{if(e.target===e.currentTarget)setShowNew(false)}}><form className="modalCard" onSubmit={addControl}><div className="sectionTitle"><h3>Novo controle</h3><button type="button" className="link" onClick={()=>setShowNew(false)}>✕</button></div><Field l="Nome *"><input autoFocus required placeholder="Ex.: Viagem, Casa, Pai - Despesas" value={newControl.nome} onChange={e=>setNewControl({...newControl,nome:e.target.value})}/></Field><Field l="Descrição"><textarea value={newControl.descricao} onChange={e=>setNewControl({...newControl,descricao:e.target.value})}/></Field><div className="modalActions"><button type="button" className="ghost" onClick={()=>setShowNew(false)}>Cancelar</button><button className="primary">Criar controle</button></div></form></div>}</>}

function Organizations({organizations,organization,members,currentUser,switchOrganization,createOrganization,inviteMember,changeMember,removeMember}){const [show,setShow]=useState(false);const [nome,setNome]=useState('');const [email,setEmail]=useState('');const [role,setRole]=useState('editor');const owner=organization?.owner_id===currentUser.id;async function addOrg(e){e.preventDefault();if(await createOrganization({nome})){setNome('');setShow(false)}}async function invite(e){e.preventDefault();if(await inviteMember(email,role))setEmail('')}return <><div className="sectionTitle controlHeader"><div><h3>Organizações / Workspaces</h3><p>Cada organização isola membros, controles, categorias e dados financeiros.</p></div><button className="primary" onClick={()=>setShow(true)}>＋ Nova organização</button></div><div className="controlCards">{organizations.map(o=><button key={o.id} className={'controlCard '+(o.id===organization?.id?'selected':'')} onClick={()=>switchOrganization(o.id)}><span>{o.owner_id===currentUser.id?'Proprietário':'Membro'}</span><b>{o.nome}</b><small>{o.email||'Workspace ContaClaraAI'}</small></button>)}</div>{organization&&<div className="grid2 controlAdmin"><div className="card"><h3>Workspace atual</h3><dl><div><dt>Organização</dt><dd>{organization.nome}</dd></div><div><dt>Seu acesso</dt><dd>{owner?'Proprietário':'Membro'}</dd></div><div><dt>Membros</dt><dd>{members.length+(owner?1:0)}</dd></div></dl><p className="muted">Os controles e categorias exibidos no sistema pertencem somente a este workspace.</p></div><div className="card"><h3>Membros da organização</h3><p className="muted">Administrador gerencia o workspace; Editor altera dados; Visualizador consulta.</p>{owner&&<form className="inviteForm" onSubmit={invite}><Field l="E-mail"><input type="email" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="pessoa@email.com"/></Field><Field l="Permissão"><select value={role} onChange={e=>setRole(e.target.value)}><option value="administrador">Administrador</option><option value="editor">Editor</option><option value="visualizador">Visualizador</option></select></Field><button className="primary">Convidar</button></form>}<div className="memberList"><div className="memberRow ownerRow"><div className="avatar">{(owner?currentUser.email:'ORG').slice(0,2).toUpperCase()}</div><div><b>{owner?currentUser.email:'Proprietário da organização'}</b><small>Proprietário</small></div></div>{members.map(m=><div className="memberRow" key={m.id}><div className="avatar">{m.email.slice(0,2).toUpperCase()}</div><div><b>{m.email}</b><small>{m.status==='ativo'?'Acesso ativo':'Convite pendente'}</small></div>{owner?<select value={m.papel} onChange={e=>changeMember(m.id,e.target.value)}><option value="administrador">Administrador</option><option value="editor">Editor</option><option value="visualizador">Visualizador</option></select>:<span className="roleBadge">{m.papel}</span>}{owner&&<button className="memberRemove" onClick={()=>removeMember(m.id)}>Remover</button>}</div>)}</div></div></div>}{show&&<div className="modalBackdrop"><form className="modalCard" onSubmit={addOrg}><div className="sectionTitle"><h3>Nova organização</h3><button type="button" className="link" onClick={()=>setShow(false)}>✕</button></div><Field l="Nome *"><input autoFocus required value={nome} onChange={e=>setNome(e.target.value)} placeholder="Ex.: Família Oliveira ou Empresa XYZ"/></Field><div className="modalActions"><button type="button" className="ghost" onClick={()=>setShow(false)}>Cancelar</button><button className="primary">Criar workspace</button></div></form></div>}</>}

function Settings({settings,save}){const base={nome_empresa:'ContaClaraAI',nome_exibicao:'',documento:'',email:'',telefone:'',cep:'',endereco:'',numero:'',complemento:'',bairro:'',cidade:'',uf:'',cor_primaria:'#0877f9'};const [f,setF]=useState({...base,...(settings||{})});const [logo,setLogo]=useState(null);const [busy,setBusy]=useState(false);useEffect(()=>setF({...base,...(settings||{})}),[settings?.id,settings?.updated_at]);const upd=(k,v)=>setF({...f,[k]:v});async function submit(e){e.preventDefault();if(!f.nome_empresa.trim())return;setBusy(true);await save(f,logo);setBusy(false);setLogo(null)}return <form onSubmit={submit}><div className="settingsGrid"><div className="card"><h3>Identidade visual</h3><p className="muted">Personalize como o ContaClaraAI aparece para os usuários.</p><Field l="Nome da empresa / organização *"><input required value={f.nome_empresa} onChange={e=>upd('nome_empresa',e.target.value)}/></Field><Field l="Nome de exibição"><input placeholder="Ex.: Família Oliveira" value={f.nome_exibicao||''} onChange={e=>upd('nome_exibicao',e.target.value)}/></Field><Field l="Cor principal"><div className="colorField"><input type="color" value={f.cor_primaria||'#0877f9'} onChange={e=>upd('cor_primaria',e.target.value)}/><input value={f.cor_primaria||''} onChange={e=>upd('cor_primaria',e.target.value)}/></div></Field><Field l="Logotipo"><label className="upload settingsLogoUpload">{logo?<strong>{logo.name}</strong>:settings?.logo_url?<img src={settings.logo_url} alt="Logotipo atual"/>:<><b>⇧</b><strong>Selecionar logotipo</strong></>}<small>PNG, JPG, WEBP ou SVG · máximo 5 MB</small><input type="file" accept="image/png,image/jpeg,image/webp,image/svg+xml" onChange={e=>setLogo(e.target.files?.[0]||null)}/></label></Field><div className="brandPreview" style={{'--preview':f.cor_primaria||'#0877f9'}}>{(logo||settings?.logo_url)?<div className="previewLogo">{logo?<span>Nova logo</span>:<img src={settings.logo_url} alt="Logo"/>}</div>:<div className="previewLetter">{(f.nome_exibicao||f.nome_empresa||'C').slice(0,1).toUpperCase()}</div>}<div><b>{f.nome_exibicao||f.nome_empresa||'ContaClaraAI'}</b><small>Controle inteligente</small></div></div></div><div className="card"><h3>Dados cadastrais e contato</h3><p className="muted">Esses dados poderão ser utilizados nos relatórios e prestações de contas.</p><div className="fields"><Field l="CPF / CNPJ"><input value={f.documento||''} onChange={e=>upd('documento',e.target.value)}/></Field><Field l="Telefone / WhatsApp"><input value={f.telefone||''} onChange={e=>upd('telefone',e.target.value)}/></Field><Field l="E-mail"><input type="email" value={f.email||''} onChange={e=>upd('email',e.target.value)}/></Field><Field l="CEP"><input value={f.cep||''} onChange={e=>upd('cep',e.target.value)}/></Field><Field l="Endereço"><input value={f.endereco||''} onChange={e=>upd('endereco',e.target.value)}/></Field><Field l="Número"><input value={f.numero||''} onChange={e=>upd('numero',e.target.value)}/></Field><Field l="Complemento"><input value={f.complemento||''} onChange={e=>upd('complemento',e.target.value)}/></Field><Field l="Bairro"><input value={f.bairro||''} onChange={e=>upd('bairro',e.target.value)}/></Field><Field l="Cidade"><input value={f.cidade||''} onChange={e=>upd('cidade',e.target.value)}/></Field><Field l="UF"><input maxLength="2" value={f.uf||''} onChange={e=>upd('uf',e.target.value.toUpperCase())}/></Field></div><div className="settingsActions"><button type="button" className="ghost" onClick={()=>setF({...base,...(settings||{})})}>Descartar alterações</button><button className="primary" disabled={busy||!f.nome_empresa.trim()}>{busy?'Salvando...':'Salvar configurações'}</button></div></div></div></form>}
function People({rows}){const sum=rows.reduce((a,r)=>{a[r.payer]=(a[r.payer]||0)+Number(r.value);return a},{});return <div className="categoryGrid">{Object.entries(sum).map(([p,v])=><div className="card category" key={p}><div className="avatar">{p.slice(0,2).toUpperCase()}</div><div><b>{p}</b><small>Total pago: {money(v)}</small></div></div>)}</div>}
function Billing({organization,subscription,usage,currentUser,reload}){
 const [busy,setBusy]=useState(''); const [msg,setMsg]=useState('');
 const plan=subscription?.planos_saas||{codigo:'free',nome:'Free',preco_mensal:0,limite_controles:1,limite_membros:2,limite_ia_mes:10,limite_armazenamento_mb:100};
 const trial=subscription?.status==='trial'; const end=trial?subscription?.trial_fim:(subscription?.proxima_cobranca||subscription?.periodo_fim); const days=end?Math.max(0,Math.ceil((new Date(end)-new Date())/86400000)):null;
 const limits=[['Controles',usage?.controles,plan.limite_controles],['Membros',usage?.membros,plan.limite_membros],['Análises IA',usage?.ia_mes,plan.limite_ia_mes],['Armazenamento (MB)',usage?.armazenamento_mb,plan.limite_armazenamento_mb]]; const pct=(v,l)=>Math.min(100,Math.round((Number(v||0)/Number(l||1))*100));
 async function api(path,body){setBusy(path);setMsg('');try{let {data:{session}}=await supabase.auth.getSession();if(!session?.access_token)throw new Error('Sessão expirada. Entre novamente.');const expiresSoon=session.expires_at&&session.expires_at*1000-Date.now()<60000;if(expiresSoon){const refreshed=await supabase.auth.refreshSession();session=refreshed.data.session;if(refreshed.error||!session?.access_token)throw new Error('Não foi possível renovar sua sessão. Entre novamente.')}const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json','Authorization':`Bearer ${session.access_token}`},body:JSON.stringify(body)});let j={};try{j=await r.json()}catch{}if(r.status===401)throw new Error(j.error||'Sessão inválida ou expirada. Entre novamente.');if(!r.ok)throw new Error(j.error||(j.code?`Falha na operação (${j.code}).`:'Falha na operação.'));return j}catch(e){setMsg(e.message);return null}finally{setBusy('')}}
 async function checkout(code){const j=await api('/api/billing/checkout',{organizationId:organization.id,planCode:code,payerEmail:currentUser?.email});if(j?.checkoutUrl)window.location.href=j.checkoutUrl}
 async function sync(){const j=await api('/api/billing/sync',{organizationId:organization.id});if(j){setMsg('Assinatura sincronizada com o Mercado Pago.');await reload()}}
 async function cancel(){if(!confirm('Cancelar a renovação desta assinatura?'))return;const j=await api('/api/billing/cancel',{organizationId:organization.id});if(j){setMsg('Assinatura cancelada.');await reload()}}
 const activePaid=subscription?.provedor==='mercado_pago'&&subscription?.assinatura_externa_id&&['ativo','trial','inadimplente'].includes(subscription?.status);
 return <div className="billingPage"><div className="card billingHero"><div><span className="planEyebrow">PLANO ATUAL</span><h2>{plan.nome}</h2><p>{trial?`Período de avaliação · ${days} dia(s) restante(s)`:(subscription?.status==='ativo'?'Assinatura ativa':subscription?.status==='inadimplente'?'Pagamento pendente':subscription?.status==='cancelado'?'Assinatura cancelada':'Plano gratuito')}</p></div><div className="planPrice"><strong>{money(Number(plan.preco_mensal||0))}</strong><span>/mês</span></div></div>{msg&&<div className="notice">{msg}</div>}<div className="grid2"><div className="card"><h3>Uso e limites</h3><p className="muted">Consumo do workspace <b>{organization?.nome}</b>.</p><div className="quotaList">{limits.map(([label,val,lim])=><div className="quota" key={label}><div><span>{label}</span><b>{Number(val||0)} de {lim??'Ilimitado'}</b></div><div className="quotaBar"><i style={{width:`${lim?pct(val,lim):0}%`}}></i></div></div>)}</div></div><div className="card"><h3>Assinatura</h3><dl><div><dt>Status</dt><dd>{trial?'Trial':subscription?.status==='ativo'?'Ativa':subscription?.status==='inadimplente'?'Pendente':subscription?.status==='cancelado'?'Cancelada':'Free'}</dd></div><div><dt>Workspace</dt><dd>{organization?.nome||'-'}</dd></div><div><dt>Próxima cobrança</dt><dd>{end?formatDate(String(end).slice(0,10)):'—'}</dd></div><div><dt>Cobrança</dt><dd>{subscription?.provedor==='mercado_pago'?'Mercado Pago':'Sem cobrança'}</dd></div></dl>{activePaid&&<div className="actions"><button className="ghost" onClick={sync} disabled={!!busy}>Sincronizar</button><button className="danger" onClick={cancel} disabled={!!busy}>Cancelar assinatura</button></div>}</div></div><div className="sectionTitle pricingTitle"><div><h3>Planos ContaClaraAI</h3><p>Assinaturas recorrentes processadas pelo Mercado Pago.</p></div></div><div className="pricingGrid"><PlanCard name="Free" price="R$ 0" items={['1 controle','2 membros','10 análises IA/mês','100 MB de arquivos']} current={plan.codigo==='free'}/><PlanCard name="Plus" price="R$ 29,90" items={['5 controles','10 membros','150 análises IA/mês','2 GB de arquivos','Prestação de contas']} current={plan.codigo==='plus'} featured onChoose={()=>checkout('plus')} busy={!!busy}/><PlanCard name="Pro" price="R$ 69,90" items={['Controles ampliados','30 membros','600 análises IA/mês','10 GB de arquivos','Auditoria e identidade']} current={plan.codigo==='pro'} onChoose={()=>checkout('pro')} busy={!!busy}/></div></div>
}
function PlanCard({name,price,items,current,featured,onChoose,busy}){return <div className={'card planCard '+(featured?'featured':'')}><div><h3>{name}</h3><strong>{price}</strong><span>/mês</span></div><ul>{items.map(x=><li key={x}>✓ {x}</li>)}</ul><button className={current?'ghost':'primary'} disabled={current||busy||!onChoose} onClick={onChoose}>{current?'Plano atual':busy?'Aguarde...':'Assinar com Mercado Pago'}</button></div>}

function Finance({rows,budgets,recurrences,splits,categories,saveBudget,saveRecurrence,toggleRecurrence,saveSplit}){const now=new Date();const ym=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`;const monthRows=rows.filter(r=>r.date?.startsWith(ym));const spent=monthRows.reduce((a,r)=>a+Number(r.value),0);const current=budgets.find(b=>String(b.mes).startsWith(ym)&&!b.categoria);const limit=Number(current?.limite_geral||0);const missingProof=rows.filter(r=>!r.proof).length;const pending=rows.filter(r=>r.status==='Pendente').length;const noCat=rows.filter(r=>!r.cat||r.cat==='Outros').length;const pix={};rows.forEach(r=>{if(r.pixTransactionId)pix[r.pixTransactionId]=(pix[r.pixTransactionId]||0)+1});const duplicates=Object.values(pix).filter(n=>n>1).length;const [budget,setBudget]=useState({mes:ym,limite_geral:'',categoria:'',limite_categoria:''});const [rec,setRec]=useState({descricao:'',categoria:categories?.[0]?.nome||'Outros',valor:'',dia_vencimento:'1',pagador:'',fornecedor:'',forma_pagamento:'PIX'});const [split,setSplit]=useState({descricao:'',valor_total:'',pago_por:'',participantes:'',observacoes:''});return <><div className="cards financeCards"><Metric t="Orçamento do mês" v={limit?money(limit):'Não definido'} icon="◎"/><Metric t="Realizado" v={money(spent)} icon="▤"/><Metric t="Disponível" v={limit?money(Math.max(0,limit-spent)):'—'} icon="◈"/><Metric t="Utilização" v={limit?`${Math.round(spent/limit*100)}%`:'—'} icon="◉"/></div><div className="grid2"><div className="card"><h3>Central de Pendências</h3><div className="pendingList"><div><b>{missingProof}</b><span>Despesas sem comprovante</span></div><div><b>{pending}</b><span>Pagamentos pendentes</span></div><div><b>{noCat}</b><span>Itens em “Outros”/sem categoria</span></div><div><b>{duplicates}</b><span>Possíveis PIX duplicados</span></div></div></div><div className="card"><h3>Orçamento mensal</h3><div className="fields"><Field l="Mês"><input type="month" value={budget.mes} onChange={e=>setBudget({...budget,mes:e.target.value})}/></Field><Field l="Limite geral"><input inputMode="decimal" placeholder="8000,00" value={budget.limite_geral} onChange={e=>setBudget({...budget,limite_geral:e.target.value.replace(',','.')})}/></Field><Field l="Categoria (opcional)"><select value={budget.categoria} onChange={e=>setBudget({...budget,categoria:e.target.value})}><option value="">Geral</option>{categories.map(c=><option key={c.id}>{c.nome}</option>)}</select></Field><Field l="Limite da categoria"><input inputMode="decimal" value={budget.limite_categoria} onChange={e=>setBudget({...budget,limite_categoria:e.target.value.replace(',','.')})}/></Field></div><button className="primary" onClick={()=>saveBudget(budget)}>Salvar orçamento</button></div></div><div className="grid2 financeSection"><div className="card"><h3>Despesas recorrentes</h3><div className="fields"><Field l="Descrição"><input value={rec.descricao} onChange={e=>setRec({...rec,descricao:e.target.value})}/></Field><Field l="Valor"><input inputMode="decimal" value={rec.valor} onChange={e=>setRec({...rec,valor:e.target.value.replace(',','.')})}/></Field><Field l="Categoria"><select value={rec.categoria} onChange={e=>setRec({...rec,categoria:e.target.value})}>{categories.map(c=><option key={c.id}>{c.nome}</option>)}</select></Field><Field l="Dia do vencimento"><input type="number" min="1" max="31" value={rec.dia_vencimento} onChange={e=>setRec({...rec,dia_vencimento:e.target.value})}/></Field><Field l="Pagador"><input value={rec.pagador} onChange={e=>setRec({...rec,pagador:e.target.value})}/></Field><Field l="Fornecedor"><input value={rec.fornecedor} onChange={e=>setRec({...rec,fornecedor:e.target.value})}/></Field></div><button className="primary" disabled={!rec.descricao||!rec.valor} onClick={()=>saveRecurrence(rec)}>Adicionar recorrência</button><div className="simpleList">{recurrences.map(r=><div key={r.id}><span><b>{r.descricao}</b><small>Dia {r.dia_vencimento} · {r.categoria}</small></span><strong>{money(r.valor)}</strong><button className="link" onClick={()=>toggleRecurrence(r)}>{r.ativo?'Pausar':'Ativar'}</button></div>)}</div></div><div className="card"><h3>Rateio / Reembolso</h3><div className="fields"><Field l="Descrição"><input value={split.descricao} onChange={e=>setSplit({...split,descricao:e.target.value})}/></Field><Field l="Valor total"><input inputMode="decimal" value={split.valor_total} onChange={e=>setSplit({...split,valor_total:e.target.value.replace(',','.')})}/></Field><Field l="Pago por"><input value={split.pago_por} onChange={e=>setSplit({...split,pago_por:e.target.value})}/></Field><Field l="Participantes"><input placeholder="Thais, Vinicius, Cleia" value={split.participantes} onChange={e=>setSplit({...split,participantes:e.target.value})}/></Field></div><Field l="Observações"><textarea value={split.observacoes} onChange={e=>setSplit({...split,observacoes:e.target.value})}/></Field><button className="primary" disabled={!split.descricao||!split.valor_total||!split.pago_por} onClick={()=>saveSplit(split)}>Registrar rateio</button><div className="simpleList">{splits.map(r=>{const ps=r.participantes||[];const quota=ps.length?Number(r.valor_total)/ps.length:0;return <div key={r.id}><span><b>{r.descricao}</b><small>{r.pago_por} pagou · {ps.length} participantes · cota {money(quota)}</small></span><strong>{money(r.valor_total)}</strong></div>})}</div></div></div></>}
function Metric({t,v,icon}){return <div className="metric"><div className="metricIcon">{icon}</div><div><span>{t}</span><strong>{v}</strong></div></div>}


function BankReconciliation({transactions,rows,categories,controle,organization,session,reload,setNotice}){
 const [file,setFile]=useState(null),[busy,setBusy]=useState(false),[aiBusy,setAiBusy]=useState(null),[filter,setFilter]=useState('pendente'),[batchBusy,setBatchBusy]=useState(false),[suggestCategories,setSuggestCategories]=useState(true);
 const pending=transactions.filter(x=>x.status_conciliacao==='pendente').length,matched=transactions.filter(x=>x.status_conciliacao==='conciliado').length;
 const visible=filter==='todos'?transactions:transactions.filter(x=>x.status_conciliacao===filter);
 function parseMoney(v){let x=String(v??'').trim().replace(/R\$/gi,'').replace(/\s/g,'');if(x.includes(',')&&x.includes('.'))x=x.lastIndexOf(',')>x.lastIndexOf('.')?x.replace(/\./g,'').replace(',','.'):x.replace(/,/g,'');else if(x.includes(','))x=x.replace(',','.');return Number(x)||0}
 function parseDate(v){const x=String(v||'').trim();let m=x.match(/^(\d{4})(\d{2})(\d{2})/);if(m)return `${m[1]}-${m[2]}-${m[3]}`;m=x.match(/^(\d{2})[\/\-.](\d{2})[\/\-.](\d{4})/);if(m)return `${m[3]}-${m[2]}-${m[1]}`;m=x.match(/^(\d{4})-(\d{2})-(\d{2})/);return m?`${m[1]}-${m[2]}-${m[3]}`:null}
 function tag(block,name){const m=block.match(new RegExp(`<${name}>([^<\\r\\n]+)`,'i'));return m?m[1].trim():''}
 function parseOFX(text){const blocks=text.match(/<STMTTRN>[\s\S]*?(?:<\/STMTTRN>|(?=<STMTTRN>|<\/BANKTRANLIST>))/gi)||[];return blocks.map((b,i)=>({data:parseDate(tag(b,'DTPOSTED')),valor:parseMoney(tag(b,'TRNAMT')),descricao:tag(b,'NAME')||tag(b,'MEMO')||'Movimentação bancária',memo:tag(b,'MEMO'),tipo:tag(b,'TRNTYPE'),identificador_externo:tag(b,'FITID')||`ofx-${i}-${tag(b,'DTPOSTED')}-${tag(b,'TRNAMT')}`})).filter(x=>x.data&&x.valor!==0)}
 function splitCSVLine(line,sep){let out=[],cur='',q=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'){if(q&&line[i+1]==='"'){cur+='"';i++}else q=!q}else if(c===sep&&!q){out.push(cur);cur=''}else cur+=c}out.push(cur);return out}
 function parseCSV(text){const lines=text.replace(/^\uFEFF/,'').split(/\r?\n/).filter(x=>x.trim());if(lines.length<2)return[];const sep=(lines[0].match(/;/g)||[]).length>(lines[0].match(/,/g)||[]).length?';':',';const headers=splitCSVLine(lines[0],sep).map(x=>x.trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,''));const find=(...xs)=>headers.findIndex(h=>xs.some(x=>h===x||h.includes(x)));const di=find('data','date'),vi=find('valor','amount','quantia'),de=find('descricao','description','historico','memo','lancamento'),ti=find('tipo','type'),ii=find('id','fitid','identificador'),ci=find('categoria','category');if(di<0||vi<0)throw new Error('CSV precisa conter colunas de Data e Valor.');return lines.slice(1).map((l,i)=>{const c=splitCSVLine(l,sep);return{data:parseDate(c[di]),valor:parseMoney(c[vi]),descricao:(c[de]||'Movimentação bancária').trim(),memo:c[de]||'',tipo:c[ti]||'',identificador_externo:(c[ii]||`csv-${i}-${c[di]}-${c[vi]}-${c[de]||''}`).trim(),ia_categoria:(ci>=0?c[ci]:'')?.trim()||null}}).filter(x=>x.data&&x.valor!==0)}
 async function importFile(){if(!file||!controle)return;setBusy(true);try{const text=await file.text();let list=file.name.toLowerCase().endsWith('.ofx')?parseOFX(text):parseCSV(text);if(!list.length)throw new Error('Nenhuma movimentação válida encontrada.');const {data:rules}=await supabase.from('regras_categorizacao_bancaria').select('*').eq('controle_id',controle.id).eq('ativo',true);list=list.map(x=>{if(x.ia_categoria)return x;const txt=`${x.descricao||''} ${x.memo||''}`.toLowerCase();const rule=(rules||[]).find(r=>txt.includes(String(r.termo||'').toLowerCase()));return rule?{...x,ia_categoria:rule.categoria,ia_justificativa:`Categoria aplicada pela regra aprendida: ${rule.termo}`} : x});const payload=list.map(x=>({organizacao_id:organization.id,controle_id:controle.id,user_id:session.user.id,arquivo_origem:file.name,...x,status_conciliacao:'pendente'}));const {error}=await supabase.from('transacoes_bancarias').upsert(payload,{onConflict:'controle_id,identificador_externo',ignoreDuplicates:true});if(error)throw error;setNotice(`${list.length} movimentação(ões) processada(s). Duplicidades foram ignoradas.${suggestCategories?' Use “Sugerir categorias com IA” para classificar as pendentes.':''}`);setFile(null);await reload()}catch(e){setNotice('Importação bancária: '+e.message)}finally{setBusy(false)}}
 function localSuggestion(t){const target=Math.abs(Number(t.valor));let best=null,score=0;for(const r of rows){let s=0;if(Math.abs(Number(r.value)-target)<0.01)s+=65;const days=Math.abs((new Date(r.date+'T12:00:00')-new Date(t.data+'T12:00:00'))/86400000);if(days===0)s+=20;else if(days<=2)s+=12;const txt=`${t.descricao} ${t.memo}`.toLowerCase(),who=`${r.supplier} ${r.desc}`.toLowerCase();const tokens=who.split(/\W+/).filter(x=>x.length>3);if(tokens.some(x=>txt.includes(x)))s+=15;if(s>score){score=s;best=r}}return best?{row:best,score:Math.min(score,100)}:null}
 async function analyze(t,quiet=false){if(!quiet)setAiBusy(t.id);try{const candidates=rows.filter(r=>Math.abs(Number(r.value)-Math.abs(Number(t.valor)))<0.02||Math.abs((new Date(r.date)-new Date(t.data))/86400000)<=3).slice(0,20).map(r=>({id:r.id,data:r.date,valor:r.value,descricao:r.desc,fornecedor:r.supplier,categoria:r.cat}));const token=(await supabase.auth.getSession()).data.session?.access_token;const res=await fetch('/api/ai/reconcile',{method:'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:JSON.stringify({transaction:{id:t.id,data:t.data,valor:t.valor,descricao:t.descricao,memo:t.memo,tipo:t.tipo},candidates,categories:categories.filter(c=>c.ativo).map(c=>c.nome)})});const body=await res.json();if(!res.ok)throw new Error(body.error||'Falha na análise.');const a=body.data||{};const existing=a.categoria&&categories.some(c=>c.nome.toLowerCase()===String(a.categoria).toLowerCase())?a.categoria:null;const {error}=await supabase.from('transacoes_bancarias').update({despesa_sugerida_id:a.despesa_id||null,ia_confianca:Number(a.confianca||0),ia_categoria:existing,categoria_sugerida_nova:existing?null:(a.nova_categoria||null),ia_justificativa:a.justificativa||null,updated_at:new Date().toISOString()}).eq('id',t.id);if(error)throw error;if(!quiet)await reload()}catch(e){const sug=localSuggestion(t);if(sug){await supabase.from('transacoes_bancarias').update({despesa_sugerida_id:sug.row.id,ia_confianca:sug.score,ia_categoria:sug.row.cat,categoria_sugerida_nova:null,ia_justificativa:'Sugestão local por valor, data e descrição.',updated_at:new Date().toISOString()}).eq('id',t.id);if(!quiet){setNotice('IA indisponível; aplicada sugestão local de conciliação.');await reload()}}else if(!quiet)setNotice(e.message)}finally{if(!quiet)setAiBusy(null)}}
 async function analyzeAll(){const todo=transactions.filter(x=>x.status_conciliacao==='pendente'&&!x.ia_categoria&&!x.categoria_sugerida_nova).slice(0,30);if(!todo.length){setNotice('Não há movimentações pendentes sem categoria.');return}setBatchBusy(true);try{for(const t of todo)await analyze(t,true);setNotice(`${todo.length} movimentação(ões) analisada(s). Revise as categorias sugeridas.`);await reload()}finally{setBatchBusy(false)}}
 async function createSuggestedCategory(t){const nome=String(t.categoria_sugerida_nova||'').trim();if(!nome)return;const existing=categories.find(c=>c.nome.toLowerCase()===nome.toLowerCase());let categoryName=existing?.nome;if(!existing){const {data,error}=await supabase.from('categorias').insert({user_id:session.user.id,organizacao_id:organization.id,nome,descricao:'Categoria sugerida pela conciliação bancária',ativo:true,ordem:categories.length}).select().single();if(error){setNotice(error.message);return}categoryName=data.nome}const term=String(t.descricao||'').trim().slice(0,120);if(term){await supabase.from('regras_categorizacao_bancaria').upsert({organizacao_id:organization.id,controle_id:controle.id,user_id:session.user.id,termo:term,categoria:categoryName,ativo:true},{onConflict:'controle_id,termo'}).then(()=>{}).catch(()=>{})}await supabase.from('transacoes_bancarias').update({ia_categoria:categoryName,categoria_sugerida_nova:null,updated_at:new Date().toISOString()}).eq('id',t.id);setNotice(`Categoria “${categoryName}” criada e aplicada. A classificação foi aprendida para próximas importações.`);await reload()}
 async function reconcile(t,expenseId){if(!expenseId)return;const {error}=await supabase.from('transacoes_bancarias').update({despesa_id:expenseId,status_conciliacao:'conciliado',conciliado_em:new Date().toISOString(),updated_at:new Date().toISOString()}).eq('id',t.id);if(error)setNotice(error.message);else{setNotice('Movimentação conciliada.');await reload()}}
 async function createExpense(t){const value=Math.abs(Number(t.valor));if(Number(t.valor)>0&&!confirm('Esta movimentação é uma entrada/crédito. Deseja criar uma despesa mesmo assim?'))return;const {data,error}=await supabase.from('despesas').insert({user_id:session.user.id,controle_id:controle.id,data:t.data,descricao:t.descricao||'Movimentação bancária',categoria:t.ia_categoria||'Outros',valor:value,pagador:'',fornecedor:t.descricao||'',status:'Pago',forma_pagamento:(`${t.descricao} ${t.memo}`.toUpperCase().includes('PIX')?'PIX':'Conta bancária'),observacoes:`Criada pela conciliação bancária. Arquivo: ${t.arquivo_origem||'-'}`,origem:'extrato_bancario',ia_confianca:t.ia_confianca||null}).select().single();if(error){setNotice(error.message);return}await reconcile(t,data.id)}
 async function ignore(t){const {error}=await supabase.from('transacoes_bancarias').update({status_conciliacao:'ignorado',updated_at:new Date().toISOString()}).eq('id',t.id);if(error)setNotice(error.message);else await reload()}
 return <div className="bankPage"><div className="cards"><Metric t="Movimentações" v={transactions.length} icon="▤"/><Metric t="Pendentes" v={pending} icon="!"/><Metric t="Conciliadas" v={matched} icon="✓"/><Metric t="Valor importado" v={money(transactions.reduce((a,x)=>a+Math.abs(Number(x.valor)),0))} icon="₿"/></div><div className="card bankImport"><div><h3>Importar extrato bancário</h3><p className="muted">Aceita OFX e CSV. No OFX, FITID é usado para evitar importações duplicadas.</p></div><div className="bankImportActions"><input type="file" accept=".ofx,.csv,text/csv,application/x-ofx" onChange={e=>setFile(e.target.files?.[0]||null)}/><label className="bankAiToggle"><input type="checkbox" checked={suggestCategories} onChange={e=>setSuggestCategories(e.target.checked)}/><span>Sugerir novas categorias com IA</span></label><button className="primary" disabled={!file||busy} onClick={importFile}>{busy?'Importando...':'Importar extrato'}</button></div></div><div className="sectionTitle"><div><h3>Central de Conciliação</h3><p>Associe movimentações a despesas existentes ou crie uma nova despesa.</p></div><div className="bankToolbar"><button className="ghost" disabled={batchBusy||!suggestCategories} onClick={analyzeAll}>{batchBusy?'Analisando categorias...':'Sugerir categorias com IA'}</button><select value={filter} onChange={e=>setFilter(e.target.value)}><option value="pendente">Pendentes</option><option value="conciliado">Conciliadas</option><option value="ignorado">Ignoradas</option><option value="todos">Todas</option></select></div></div><div className="bankList">{visible.length===0?<div className="card empty">Nenhuma movimentação neste filtro.</div>:visible.map(t=>{const sug=rows.find(r=>r.id===(t.despesa_sugerida_id||t.despesa_id));return <div className="card bankRow" key={t.id}><div className="bankTxn"><span className={Number(t.valor)<0?'bankDebit':'bankCredit'}>{Number(t.valor)<0?'Saída':'Entrada'}</span><b>{t.descricao}</b><small>{formatDate(t.data)} · {t.tipo||'Movimentação'}{t.memo&&t.memo!==t.descricao?` · ${t.memo}`:''}</small></div><strong className={Number(t.valor)<0?'negative':''}>{money(Number(t.valor))}</strong><div className="bankMatch">{sug?<><span>Possível correspondência {t.ia_confianca?`· ${t.ia_confianca}%`:''}</span><b>{sug.desc} — {money(sug.value)}</b></>:<span>Sem despesa correspondente</span>}{t.ia_categoria&&<small className="bankCategory">Categoria: <b>{t.ia_categoria}</b></small>}{t.categoria_sugerida_nova&&<small className="bankCategory new">Nova categoria sugerida: <b>{t.categoria_sugerida_nova}</b> <button className="miniAction" onClick={()=>createSuggestedCategory(t)}>Criar categoria</button></small>}{t.ia_justificativa&&<small>{t.ia_justificativa}</small>}</div><div className="bankActions">{t.status_conciliacao==='pendente'&&<><button className="ghost" disabled={aiBusy===t.id} onClick={()=>analyze(t)}>{aiBusy===t.id?'Analisando...':'Analisar com IA'}</button>{sug&&<button className="primary" onClick={()=>reconcile(t,sug.id)}>Confirmar</button>}<button className="ghost" onClick={()=>createExpense(t)}>Criar despesa</button><button className="link" onClick={()=>ignore(t)}>Ignorar</button></>}{t.status_conciliacao==='conciliado'&&<span className="status paid">✓ Conciliado</span>}{t.status_conciliacao==='ignorado'&&<span className="muted">Ignorado</span>}</div></div>})}</div></div>
}

function Reports({rows,organization,controle}){
 const dates=rows.map(r=>r.date).filter(Boolean).sort();
 const today=new Date().toISOString().slice(0,10);
 const firstDefault=dates[0]||today.slice(0,8)+'01'; const lastDefault=dates[dates.length-1]||today;
 const [from,setFrom]=useState(firstDefault); const [to,setTo]=useState(lastDefault);
 const filtered=useMemo(()=>rows.filter(r=>(!from||r.date>=from)&&(!to||r.date<=to)).sort((a,b)=>a.date.localeCompare(b.date)),[rows,from,to]);
 const total=filtered.reduce((a,r)=>a+Number(r.value),0); const paid=filtered.filter(r=>r.status==='Pago').reduce((a,r)=>a+Number(r.value),0); const pending=total-paid;
 const byCat=Object.entries(filtered.reduce((a,r)=>{a[r.cat||'Sem categoria']=(a[r.cat||'Sem categoria']||0)+Number(r.value);return a},{})).sort((a,b)=>b[1]-a[1]);
 const proofCount=filtered.filter(r=>r.proof).length; const pct=filtered.length?Math.round(proofCount/filtered.length*100):0;
 function csvCell(v){const x=String(v??'').replace(/"/g,'""');return `"${x}"`}
 function exportExcel(){const header=['Data','Descrição','Categoria','Valor','Pagador','Fornecedor / Recebedor','Forma de pagamento','Status','Comprovante'];const lines=[header.map(csvCell).join(';'),...filtered.map(r=>[formatDate(r.date),r.desc,r.cat,Number(r.value).toFixed(2).replace('.',','),r.payer,r.supplier,r.method,r.status,r.proof||'Sem comprovante'].map(csvCell).join(';'))];const bom='\ufeff';const blob=new Blob([bom+lines.join('\r\n')],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`prestacao-contas-${safeName(controle?.nome||'controle')}-${from||'inicio'}-${to||'fim'}.csv`;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url)}
 return <div className="reportPage"><div className="card reportFilters noPrint"><div><b>Período da prestação de contas</b><small>Selecione as datas para consolidar os lançamentos do controle atual.</small></div><Field l="Data inicial"><input type="date" value={from} onChange={e=>setFrom(e.target.value)}/></Field><Field l="Data final"><input type="date" value={to} onChange={e=>setTo(e.target.value)}/></Field><button className="ghost" onClick={()=>{setFrom(firstDefault);setTo(lastDefault)}}>Todo período</button></div><div className="reportDocument"><div className="reportIdentity">{organization?.logo_url?<img src={organization.logo_url} alt={organization.nome}/>:<div className="reportLogo">{(organization?.nome||'C').slice(0,1).toUpperCase()}</div>}<div><h2>Prestação de contas</h2><b>{organization?.nome||'ContaClaraAI'}</b><small>{[organization?.documento,organization?.telefone,organization?.email].filter(Boolean).join(' · ')}</small><small>{[organization?.endereco,organization?.numero,organization?.bairro,organization?.cidade,organization?.uf].filter(Boolean).join(', ')}</small></div><div className="reportPeriod"><span>Controle</span><b>{controle?.nome||'-'}</b><span>Período</span><b>{formatDate(from)} a {formatDate(to)}</b></div></div><Cards total={total} paid={paid} pending={pending} count={filtered.length}/><div className="grid2"><div className="card"><h3>Despesas por categoria</h3>{byCat.length?byCat.map(([c,v])=><div className="bar" key={c}><span>{c}</span><div><i style={{width:`${total?Math.max(4,v/total*100):0}%`}}></i></div><b>{money(v)}</b></div>):<div className="empty">Nenhuma despesa no período.</div>}</div><div className="card reportSummary"><h3>Conferência</h3><dl><div><dt>Lançamentos</dt><dd>{filtered.length}</dd></div><div><dt>Com comprovante</dt><dd>{proofCount}</dd></div><div><dt>Sem comprovante</dt><dd>{filtered.length-proofCount}</dd></div><div><dt>Cobertura documental</dt><dd>{pct}%</dd></div><div><dt>Total</dt><dd>{money(total)}</dd></div></dl></div></div><div className="card reportDetail"><div className="sectionTitle"><div><h3>Detalhamento dos lançamentos</h3><p className="muted">Valores consolidados para o período selecionado.</p></div></div><div className="reportTable"><div className="reportTr reportTh"><span>Data</span><span>Descrição</span><span>Categoria</span><span>Pagador</span><span>Recebedor</span><span>Comprovante</span><span>Valor</span></div>{filtered.map(r=><div className="reportTr" key={r.id}><span>{formatDate(r.date)}</span><span><b>{r.desc}</b><small>{r.method} · {r.status}</small></span><span>{r.cat}</span><span>{r.payer||'-'}</span><span>{r.supplier||'-'}</span><span className={r.proof?'proofOk':'proofMissing'}>{r.proof?'✓ Anexado':'⚠ Ausente'}</span><strong>{money(r.value)}</strong></div>)}{!filtered.length&&<div className="empty">Nenhum lançamento encontrado.</div>}</div><div className="reportTotal"><span>Total do período</span><strong>{money(total)}</strong></div></div><div className="reportActions noPrint"><button className="ghost" onClick={exportExcel}>▤ Exportar Excel (CSV)</button><button className="primary" onClick={()=>window.print()}>▣ Gerar PDF / Imprimir</button></div></div></div>
}
function formatDate(d){if(!d)return '-';const p=d.split('-');return p.length===3?`${p[2]}/${p[1]}/${p[0]}`:d}


function SaasAdmin({data,refresh}){
 const [tab,setTab]=useState('Visão geral'); const [q,setQ]=useState('');
 if(!data)return <div className="card"><h3>Administração SaaS</h3><p>Carregando indicadores...</p><button className="ghost" onClick={refresh}>Atualizar</button></div>;
 const k=data.kpis||{}, orgs=data.organizations||[], subs=data.subscriptions||[], users=data.users||[], plans=data.plans||[], ai=data.ai||[], storage=data.storage||[], members=data.members||[], controls=data.controls||[];
 const subByOrg=Object.fromEntries(subs.map(x=>[x.organizacao_id,x])); const userById=Object.fromEntries(users.map(x=>[x.id,x]));
 const count=(arr,orgId,field='organizacao_id')=>arr.filter(x=>x[field]===orgId && (x.ativo===undefined||x.ativo===true) && (x.status===undefined||x.status==='ativo')).length;
 const fmtBytes=n=>{n=Number(n||0);if(n<1024)return `${n} B`;if(n<1048576)return `${(n/1024).toFixed(1)} KB`;if(n<1073741824)return `${(n/1048576).toFixed(1)} MB`;return `${(n/1073741824).toFixed(2)} GB`};
 const filtered=orgs.filter(o=>!q||`${o.nome} ${o.email||''} ${userById[o.owner_id]?.email||''}`.toLowerCase().includes(q.toLowerCase()));
 return <div className="saasAdmin"><div className="adminHead"><div><span className="adminBadge">ACESSO INTERNO</span><h2>Administração ContaClaraAI</h2><p>Visão operacional e comercial da plataforma. Atualizado em {new Date(data.generated_at).toLocaleString('pt-BR')}.</p></div><button className="ghost" onClick={refresh}>↻ Atualizar</button></div>
 <div className="adminTabs">{['Visão geral','Clientes','Workspaces','Assinaturas','Planos','Consumo'].map(x=><button key={x} className={tab===x?'active':''} onClick={()=>setTab(x)}>{x}</button>)}</div>
 {tab==='Visão geral'&&<><div className="adminKpis"><AdminKpi label="MRR" value={money(k.mrr)} note={`ARR ${money(k.arr)}`}/><AdminKpi label="Clientes" value={k.clientes||0} note={`${k.workspaces||0} workspaces`}/><AdminKpi label="Assinaturas ativas" value={k.assinaturas_ativas||0} note={`${k.trials||0} trials`}/><AdminKpi label="Inadimplentes" value={k.inadimplentes||0} note="Acompanhar cobrança"/><AdminKpi label="IA no mês" value={k.ia_mes||0} note="análises"/><AdminKpi label="Armazenamento" value={fmtBytes(k.storage_bytes)} note="telemetria registrada"/></div><div className="grid2"><div className="card"><h3>Distribuição por plano</h3><div className="adminBars">{plans.map(p=>{const n=subs.filter(s=>s.plano_id===p.id).length;const pct=orgs.length?Math.round(n/orgs.length*100):0;return <div key={p.id}><span><b>{p.nome}</b><em>{n} · {pct}%</em></span><i><b style={{width:`${pct}%`}}/></i></div>})}</div></div><div className="card"><h3>Saúde das assinaturas</h3><dl><div><dt>Ativas</dt><dd>{k.assinaturas_ativas||0}</dd></div><div><dt>Trial</dt><dd>{k.trials||0}</dd></div><div><dt>Inadimplentes</dt><dd>{k.inadimplentes||0}</dd></div><div><dt>MRR</dt><dd>{money(k.mrr)}</dd></div></dl></div></div></>}
 {tab==='Clientes'&&<AdminTable headers={['Cliente','E-mail','Cadastro','Último acesso']} rows={users.map(u=>[u.email?.split('@')[0]||'Cliente',u.email||'—',u.created_at?new Date(u.created_at).toLocaleDateString('pt-BR'):'—',u.last_sign_in_at?new Date(u.last_sign_in_at).toLocaleString('pt-BR'):'Nunca'])}/>} 
 {tab==='Workspaces'&&<><div className="adminSearch"><input placeholder="Buscar workspace, cliente ou e-mail..." value={q} onChange={e=>setQ(e.target.value)}/></div><AdminTable headers={['Workspace','Responsável','Plano','Controles','Membros','Criado em']} rows={filtered.map(o=>{const s=subByOrg[o.id],u=userById[o.owner_id];return [o.nome,u?.email||o.email||'—',s?.planos_saas?.nome||'Free',count(controls,o.id),count(members,o.id),new Date(o.created_at).toLocaleDateString('pt-BR')]})}/></>}
 {tab==='Assinaturas'&&<AdminTable headers={['Workspace','Plano','Status','Valor','Próxima cobrança','Provedor']} rows={subs.map(s=>{const o=orgs.find(x=>x.id===s.organizacao_id);return [o?.nome||s.organizacao_id,s.planos_saas?.nome||'—',s.status,money(Number(s.valor??s.planos_saas?.preco_mensal??0)),s.proxima_cobranca?new Date(s.proxima_cobranca).toLocaleDateString('pt-BR'):'—',s.provedor||'Interno']})}/>} 
 {tab==='Planos'&&<div className="pricingGrid">{plans.map(p=><div className="card planCard" key={p.id}><div><h3>{p.nome}</h3><strong>{money(Number(p.preco_mensal))}</strong><span>/mês</span></div><ul><li>✓ {p.limite_controles??'∞'} controles</li><li>✓ {p.limite_membros??'∞'} membros</li><li>✓ {p.limite_ia_mes??'∞'} análises IA/mês</li><li>✓ {p.limite_armazenamento_mb??'∞'} MB</li></ul><small>{subs.filter(s=>s.plano_id===p.id).length} workspace(s)</small></div>)}</div>}
 {tab==='Consumo'&&<AdminTable headers={['Workspace','IA (mês)','Armazenamento','Arquivos','Atualização']} rows={orgs.map(o=>{const iaN=ai.filter(x=>x.organizacao_id===o.id&&String(x.competencia).slice(0,7)===new Date().toISOString().slice(0,7)).reduce((n,x)=>n+Number(x.quantidade||0),0),st=storage.find(x=>x.organizacao_id===o.id);return [o.nome,iaN,fmtBytes(st?.bytes_utilizados||0),st?.arquivos||0,st?.updated_at?new Date(st.updated_at).toLocaleString('pt-BR'):'—']})}/>} 
 </div>
}
function AdminKpi({label,value,note}){return <div className="card adminKpi"><span>{label}</span><strong>{value}</strong><small>{note}</small></div>}
function AdminTable({headers,rows}){return <div className="card adminTableWrap"><div className="adminTable"><div className="adminTr adminTh">{headers.map(h=><b key={h}>{h}</b>)}</div>{rows.length?rows.map((r,i)=><div className="adminTr" key={i}>{r.map((v,j)=><span key={j}>{String(v??'—')}</span>)}</div>):<div className="adminEmpty">Nenhum registro encontrado.</div>}</div></div>}
